    methods.insert("remove_port".to_string(), remove_port_method);
    methods.insert("list_bridges".to_string(), list_bridges_method);
    methods.insert("list_ports".to_string(), list_ports_method);
    methods.insert("list_dbs".to_string(), list_dbs_method);

    PluginSchema::builder("rovs_commands")
        .version("1.0.0")
        .category("network")
        .description("Direct OVSDB command execution methods exposed via D-Bus by grpc-bridge")
        .dependency("net")
        .field(
