//! rovs_commands Plugin — Direct OVSDB Command Execution via D-Bus
//!
//! Schema-only plugin defining callable methods for OVSDB operations.
//! The grpc-bridge exposes these as D-Bus objects at `/org/opdbus/v1/plugins/rovs_commands`
//! that can be called directly via zbus/busctl. No separate ovsdb_daemon needed - the
//! grpc-bridge creates the D-Bus objects and methods from this schema.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane. Methods execute OVSDB transact
//! calls directly through the rovs proxy.

use op_state_store::{FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
use simd_json::json;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

/// rovs_commands Plugin — Command definitions schema
///
/// This plugin exposes callable D-Bus methods for OVSDB operations.
/// Every method is declared in the schema and exposed by the grpc-bridge.
pub struct RovsCommandsPlugin;

impl Default for RovsCommandsPlugin {
    fn default() -> Self {
        Self::new()
    }
}

impl RovsCommandsPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Get the current state (empty - this plugin provides methods, not state)
    pub fn current_state() -> Value {
        simd_json::json!({
            "available": true,
            "schema_version": "1.0.0",
        })
    }

    /// Return the plugin schema
    pub fn schema() -> Option<PluginSchema> {
        Some(rovs_commands_schema())
    }
}

#[async_trait::async_trait]
impl op_state::StatePlugin for RovsCommandsPlugin {
    fn name(&self) -> &str {
        "rovs_commands"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Self::schema()
    }

    async fn calculate_diff(
        &self,
        _current: &Value,
        _desired: &Value,
    ) -> anyhow::Result<op_state::StateDiff> {
        // Schema-only plugin: no state to apply
        Ok(op_state::StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: op_state::DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-only".to_string(),
                desired_hash: "schema-only".to_string(),
            },
        })
    }

    async fn apply_state(
        &self,
        _diff: &op_state::StateDiff,
    ) -> anyhow::Result<op_state::ApplyResult> {
        // Schema-only plugin: no state to apply
        Ok(op_state::ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> anyhow::Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> anyhow::Result<op_state::Checkpoint> {
        Ok(op_state::Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!(null),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &op_state::Checkpoint) -> anyhow::Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> op_state::PluginCapabilities {
        op_state::PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: false,
            supports_verification: false,
            atomic_operations: false,
        }
    }
}

pub(crate) fn rovs_commands_schema() -> PluginSchema {
    use op_state_store::MethodDecl;

    // Method declarations for direct OVSDB operations via D-Bus
    let create_bridge_method = MethodDecl {
        name: "create_bridge".to_string(),
        args: json!({
            "type": "object",
            "required": ["bridge_name"],
            "properties": {
                "bridge_name": {"type": "string", "description": "Name of the bridge to create"},
                "datapath_type": {"type": "string", "default": "system"}
            }
        }),
        returns: Some(json!({"type": "object"})),
        side_effect: SideEffect::Mutation,
        idempotent: false,
        required_capability: Some("cap.network.ovsdb.bridge.create@v1".to_string()),
        subid: "mut.network.ovsdb.bridge.create@v1".to_string(),
    };

    let delete_bridge_method = MethodDecl {
        name: "delete_bridge".to_string(),
        args: json!({
            "type": "object",
            "required": ["bridge_name"],
            "properties": {
                "bridge_name": {"type": "string", "description": "Name of the bridge to delete"}
            }
        }),
        returns: Some(json!({"type": "object"})),
        side_effect: SideEffect::Mutation,
        idempotent: false,
        required_capability: Some("cap.network.ovsdb.bridge.delete@v1".to_string()),
        subid: "mut.network.ovsdb.bridge.delete@v1".to_string(),
    };

    let add_port_method = MethodDecl {
        name: "add_port".to_string(),
        args: json!({
            "type": "object",
            "required": ["bridge_name", "port_name"],
            "properties": {
                "bridge_name": {"type": "string", "description": "Parent bridge name"},
                "port_name": {"type": "string", "description": "Port name to add"},
                "interface_type": {"type": "string", "default": "internal"}
            }
        }),
        returns: Some(json!({"type": "object"})),
        side_effect: SideEffect::Mutation,
        idempotent: false,
        required_capability: Some("cap.network.ovsdb.port.add@v1".to_string()),
        subid: "mut.network.ovsdb.port.add@v1".to_string(),
    };

    let remove_port_method = MethodDecl {
        name: "remove_port".to_string(),
        args: json!({
            "type": "object",
            "required": ["port_name"],
            "properties": {
                "port_name": {"type": "string", "description": "Port name to remove"}
            }
        }),
        returns: Some(json!({"type": "object"})),
        side_effect: SideEffect::Mutation,
        idempotent: false,
        required_capability: Some("cap.network.ovsdb.port.delete@v1".to_string()),
        subid: "mut.network.ovsdb.port.delete@v1".to_string(),
    };

    let list_bridges_method = MethodDecl {
        name: "list_bridges".to_string(),
        args: json!({"type": "object"}),
        returns: Some(json!({"type": "array", "items": {"type": "string"}})),
        side_effect: SideEffect::Read,
        idempotent: true,
        required_capability: Some("cap.network.ovsdb.bridge.list@v1".to_string()),
        subid: "obs.network.ovsdb.bridge.list@v1".to_string(),
    };

    let list_ports_method = MethodDecl {
        name: "list_ports".to_string(),
        args: json!({
            "type": "object",
            "required": ["bridge_name"],
            "properties": {
                "bridge_name": {"type": "string", "description": "Bridge name to query"}
            }
        }),
        returns: Some(json!({"type": "array", "items": {"type": "string"}})),
        side_effect: SideEffect::Read,
        idempotent: true,
        required_capability: Some("cap.network.ovsdb.port.list@v1".to_string()),
        subid: "obs.network.ovsdb.port.list@v1".to_string(),
    };

    let list_dbs_method = MethodDecl {
        name: "list_dbs".to_string(),
        args: json!({"type": "object"}),
        returns: Some(json!({"type": "array", "items": {"type": "string"}})),
        side_effect: SideEffect::Read,
        idempotent: true,
        required_capability: Some("cap.network.ovsdb.db.list@v1".to_string()),
        subid: "obs.network.ovsdb.db.list@v1".to_string(),
    };

    // Build methods map
    let mut methods = HashMap::new();
    methods.insert("create_bridge".to_string(), create_bridge_method);
    methods.insert("delete_bridge".to_string(), delete_bridge_method);
    methods.insert("add_port".to_string(), add_port_method);
    methods.insert("remove_port".to_string(), remove_port_method);
    methods.insert("list_bridges".to_string(), list_bridges_method);
    methods.insert("list_ports".to_string(), list_ports_method);
    methods.insert("list_dbs".to_string(), list_dbs_method);

    PluginSchema::builder("rovs_commands")
        .version("1.0.0")
        .category("network")
        .description("Direct OVSDB command execution methods exposed via D-Bus by grpc-bridge")
        .dependency("net")
        .field(
            "available",
            FieldSchema {
                field_type: FieldType::Boolean,
                required: true,
                description: "Plugin is available".to_string(),
                default: Some(json!(true)),
                example: Some(json!(true)),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        )
        .field(
            "schema_version",
            FieldSchema {
                field_type: FieldType::String,
                required: false,
                description: "Schema version".to_string(),
                default: Some(json!("1.0.0")),
                example: Some(json!("1.0.0")),
                constraints: Vec::new(),
                read_only: true,
                read_only_when: None,
            },
        )
        .methods(methods)
        .build()
}

// Self-registration: the plugin registry discovers this via inventory
