//! ovs-attach — D-Bus client that calls BringUpLoopback and AttachPort
//! for container bootstrap.
//!
//! Discovers all config from the D-Bus tree under:
//! - /org/opdbus/v1/plugins/oci (loopback_required, port_attach per container)
//! - /org/opdbus/v1/plugins/privacy_router (bridge, port, IPs — fallback)
//!
//! No hardcoded bus names, paths, or IP addresses. The schema IS the config.

use anyhow::{Context, Result};
use serde_json::Value;
use std::path::Path;
use std::process::Command;
use std::thread;
use std::time::Duration;
use zbus::connection::Builder;

const DBUS_SOCKET: &str = "/run/op-dbus.sock";
const PLUGIN_BUS: &str = op_core::config::OPDBUS_BUS_NAME;
const PRIVACY_ROUTER_BASE: &str = "/org/opdbus/v1/plugins/privacy_router";
const OCI_BASE: &str = "/org/opdbus/v1/plugins/oci";

async fn get_json_property(conn: &zbus::Connection, path: &str, prop: &str) -> Result<Value> {
    let iface = "org.opdbus.ProjectedObjectV1".to_string();
    let msg = conn
        .call_method(
            Some(PLUGIN_BUS),
            path,
            Some("org.freedesktop.DBus.Properties"),
            "Get",
            &(&iface, prop),
        )
        .await?;
    let body = msg.body();
    let reply: zbus::zvariant::Value = body.deserialize()?;

    if let zbus::zvariant::Value::Str(s) = reply {
        Ok(serde_json::from_str(&s)?)
    } else {
        anyhow::bail!("expected string property, got {:?}", reply)
    }
}

/// Discover the proxy path on the ovsdb daemon bus by introspecting the tree.
async fn discover_proxy_path(conn: &zbus::Connection, dbus_bus: &str) -> Result<String> {
    let tree_msg = conn
        .call_method(
            Some(dbus_bus),
            "/",
            Some("org.freedesktop.DBus.Introspectable"),
            "Introspect",
            &(),
        )
        .await?;
    let introspect_xml: String = tree_msg.body().deserialize()?;

    if introspect_xml.contains("opdbus") {
        let rovs_msg = conn
            .call_method(
                Some(dbus_bus),
                "/org/opdbus/rovs",
                Some("org.freedesktop.DBus.Introspectable"),
                "Introspect",
                &(),
            )
            .await?;
        let rovs_xml: String = rovs_msg.body().deserialize()?;

        if rovs_xml.contains("proxy") {
            return Ok("/org/opdbus/rovs/proxy".to_string());
        }
    }
    anyhow::bail!("could not find proxy node in ovsdb daemon tree")
}

/// Read this container's config from the OCI plugin schema.
/// Returns (loopback_required, port_attach_config).
async fn read_oci_container_config(
    conn: &zbus::Connection,
    instance_name: &str,
) -> Result<(bool, Option<Value>)> {
    let oci_schema = get_json_property(conn, OCI_BASE, "JsonData").await?;

    if let Some(containers) = oci_schema["config"]["containers"].as_array() {
        for c in containers {
            if c["name"].as_str() == Some(instance_name) {
                let lo = c["loopback_required"].as_bool().unwrap_or(false);
                let port = c.get("port_attach").cloned();
                return Ok((lo, port));
            }
        }
    }
    Ok((false, None))
}

#[tokio::main]
async fn main() -> Result<()> {
    // Wait for D-Bus socket
    eprintln!("waiting for D-Bus socket at {DBUS_SOCKET}...");
    for _ in 0..60 {
        if Path::new(DBUS_SOCKET).exists() {
            break;
        }
        thread::sleep(Duration::from_secs(1));
    }
    anyhow::ensure!(
        Path::new(DBUS_SOCKET).exists(),
        "D-Bus socket not found after 60s"
    );

    // Connect to D-Bus
    let address = format!("unix:path={DBUS_SOCKET}");
    eprintln!("connecting to D-Bus...");
    let conn = Builder::address(&*address)?
        .build()
        .await
        .context("connect to D-Bus")?;

    // Read instance name from hostname (incus sets hostname = instance name)
    let instance_name = std::fs::read_to_string("/etc/hostname")
        .unwrap_or_default()
        .trim()
        .to_string();
    if instance_name.is_empty() {
        anyhow::bail!("could not read /etc/hostname for instance name");
    }
    eprintln!("instance_name={instance_name}");

    // ── Step 1: Read this container's config from the OCI plugin schema ──
    eprintln!("reading OCI plugin schema from D-Bus tree...");
    let (loopback_required, port_attach_config) = read_oci_container_config(&conn, &instance_name)
        .await
        .unwrap_or((false, None));

    // ── Step 2: Bring up loopback if the OCI schema declares it ────────
    if loopback_required {
        eprintln!("loopback_required=true for {instance_name}, calling BringUpLoopback...");

        let daemon =
            get_json_property(&conn, "/org/opdbus/v1/plugins/ovsdb_daemon", "JsonData").await?;
        let dbus_bus = daemon["dbus_bus_name"]
            .as_str()
            .unwrap_or("org.opdbus.v1.plugins.ovsdb");
        let proxy_path = discover_proxy_path(&conn, dbus_bus).await?;

        let lo_params = serde_json::json!({
            "instance_name": instance_name
        });

        let lo_result: String = conn
            .call_method(
                Some(dbus_bus),
                proxy_path.as_str(),
                Some("org.opdbus.rovs.proxy"),
                "BringUpLoopback",
                &(lo_params.to_string()),
            )
            .await?
            .body()
            .deserialize()?;

        eprintln!("BringUpLoopback result: {lo_result}");
    } else {
        eprintln!("loopback_required=false for {instance_name}, skipping lo bring-up");
    }

    // ── Step 3: Attach OVS port ─────────────────────────────────────────
    // If the OCI schema has port_attach config, use it directly.
    // Otherwise fall back to the privacy_router schema for the xray container.
    let (params, _bridge, socket_port) = if let Some(pa) = &port_attach_config {
        let bridge = pa["bridge"].as_str().unwrap_or("ovsbr0").to_string();
        let iface_name = pa["iface_name"].as_str().unwrap_or("gbr_xray").to_string();
        let ip_addrs: Vec<Value> = pa["ip_addrs"].as_array().cloned().unwrap_or_default();
        let gateway = pa["gateway"].as_str().map(String::from);
        let routes: Vec<Value> = pa["routes"].as_array().cloned().unwrap_or_default();

        let p = serde_json::json!({
            "port_name": format!("c_{}", iface_name),
            "bridge": bridge,
            "instance_name": instance_name,
            "iface_name": iface_name,
            "ip_addrs": ip_addrs,
            "gateway": gateway,
            "routes": routes
        });
        (p, bridge.clone(), iface_name)
    } else {
        // Fallback: read from privacy_router schema (for the host xray path;
        // the deprecated wg-xray container is no longer referenced)
        eprintln!("reading privacy_router schema from D-Bus tree...");
        let schema = get_json_property(&conn, PRIVACY_ROUTER_BASE, "JsonData").await?;

        let bridge = schema["config"]["bridge_name"]
            .as_str()
            .unwrap_or("ovsbr0")
            .to_string();
        let socket_port = schema["config"]["xray"]["socket_port"]
            .as_str()
            .unwrap_or("gbr_xray")
            .to_string();
        let container_id = schema["config"]["xray"]["container_id"]
            .as_u64()
            .unwrap_or(101);

        eprintln!("bridge={bridge}, socket_port={socket_port}, container_id={container_id}");

        let p = serde_json::json!({
            "port_name": format!("c{}_{}", container_id, socket_port),
            "bridge": bridge,
            "instance_name": instance_name,
            "iface_name": socket_port,
            "ip_addrs": ["10.200.0.1/30", "10.0.0.2/24"],
            "gateway": "10.200.0.2",
            "routes": ["10.0.0.1 via 10.200.0.2"]
        });
        (p, bridge, socket_port)
    };

    // Check if interface already exists
    if Command::new("ip")
        .args(["link", "show", &socket_port])
        .output()
        .is_ok_and(|o| o.status.success())
    {
        eprintln!("interface {socket_port} already exists, skipping AttachPort");
        return Ok(());
    }

    // Discover AttachPort method location
    let daemon =
        get_json_property(&conn, "/org/opdbus/v1/plugins/ovsdb_daemon", "JsonData").await?;
    let dbus_bus = daemon["dbus_bus_name"]
        .as_str()
        .unwrap_or("org.opdbus.v1.plugins.ovsdb");
    let proxy_path = discover_proxy_path(&conn, dbus_bus).await?;

    eprintln!("discovered AttachPort at bus={dbus_bus} path={proxy_path}");

    // Call AttachPort
    eprintln!("calling AttachPort...");
    let result: String = conn
        .call_method(
            Some(dbus_bus),
            proxy_path.as_str(),
            Some("org.opdbus.rovs.proxy"),
            "AttachPort",
            &(params.to_string()),
        )
        .await?
        .body()
        .deserialize()?;

    eprintln!("AttachPort result: {result}");

    let parsed: Value = serde_json::from_str(&result)?;
    if parsed["success"].as_bool() != Some(true) {
        anyhow::bail!("AttachPort failed: {}", parsed["message"]);
    }

    // Wait for interface to appear
    eprintln!("waiting for interface {socket_port}...");
    for _ in 0..30 {
        if Command::new("ip")
            .args(["link", "show", &socket_port])
            .output()
            .is_ok_and(|o| o.status.success())
        {
            eprintln!("interface {socket_port} is up");
            return Ok(());
        }
        thread::sleep(Duration::from_secs(1));
    }

    anyhow::bail!("interface {socket_port} not found after 30s")
}

//! op-openvswitch-daemon — Pure passthrough D-Bus proxy for rovs primitives.
//!
//! TWO separate D-Bus object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → `org.opdbus.rovs.openflow`
//!
//! The daemon is a literal passthrough: it owns the rovs crate connections
//! and exposes raw primitives over D-Bus.  Zero business logic.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane.

use anyhow::{Context, Result};
use std::path::Path;
use tracing::{info, warn};
use zbus::connection::Connection;

mod container;
mod dbus;
mod execution;
mod grpc;
mod grpc_streaming;
mod netns;

use dbus::{DaemonState, JsonRpcService, OpenFlowService, ProxyService};
use execution::PluginExecutionService;
use grpc_streaming::{EventBus, StreamingService};

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct Args {
    grpc_addr: Option<String>,
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }
        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

// ── Socket discovery ────────────────────────────────────────────────────────

const DEFAULT_OVS_SOCKET: &str = "/usr/local/var/run/openvswitch/db.sock";
const OVS_SOCKET_PATHS: &[&str] = &[
    "/usr/local/var/run/openvswitch/db.sock",
    "/run/openvswitch/db.sock",
    "/var/run/openvswitch/db.sock",
];

fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

// ── Main ────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon (pure passthrough)");

    let args = Args::parse();
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    let state = DaemonState::new(socket_path);

    // Eager-connect OVSDB so early callers don't wait.
    if let Err(e) = state.get_ovsdb().await {
        warn!(
            "Could not connect to OVSDB: {}. Will retry on first request.",
            e
        );
    }

    // Connect to the system D-Bus bus.
    // The projection server owns org.opdbus.v1.plugins on the system bus;
    // we request the distinct name org.opdbus.v1.plugins.ovsdb on the same
    // bus so rovs/* objects are reachable by clients dialing that name.
    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;
    info!("Connected to system D-Bus");

    // Register TWO separate object paths (locked design).
    let grpc_state = state.clone();
    let json_service = JsonRpcService::new(state.clone());
    let of_service = OpenFlowService::new(state.clone());
    let proxy_service = ProxyService::new(state);

    conn.object_server()
        .at("/org/opdbus/rovs/jsonrpc", json_service)
        .await
        .context("Failed to register /org/opdbus/rovs/jsonrpc")?;

    conn.object_server()
        .at("/org/opdbus/rovs/openflow", of_service)
        .await
        .context("Failed to register /org/opdbus/rovs/openflow")?;

    conn.object_server()
        .at("/org/opdbus/rovs/proxy", proxy_service)
        .await
        .context("Failed to register /org/opdbus/rovs/proxy")?;

    let exec_service = PluginExecutionService::new();
    conn.object_server()
        .at("/org/opdbus/execution", exec_service)
        .await
        .context("Failed to register /org/opdbus/execution")?;

    // Request the ovsdb plugin bus name — NOT org.opdbus.v1 (owned by op-dbus-mirror).
    conn.request_name("org.opdbus.v1.plugins.ovsdb")
        .await
        .context("Failed to request bus name org.opdbus.v1.plugins.ovsdb")?;

    info!("D-Bus services registered:");
    info!("  /org/opdbus/rovs/jsonrpc  -> org.opdbus.rovs.jsonrpc");
    info!("  /org/opdbus/rovs/openflow -> org.opdbus.rovs.openflow");
    info!("  /org/opdbus/rovs/proxy    -> org.opdbus.rovs.proxy");
    info!("  /org/opdbus/execution     -> org.opdbus.execution");

    // Optional gRPC with streaming support (M2)
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr.parse().context("Invalid --grpc address")?;
        info!("Starting gRPC server on {}", addr);

        // Create shared event bus for streaming subscriptions
        let event_bus = EventBus::new();
        let streaming_service = StreamingService::new(grpc_state.clone(), event_bus);

        tokio::spawn(async move {
            if let Err(e) =
                grpc::run_grpc_server_with_streaming(addr, grpc_state, streaming_service).await
            {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready — Ctrl+C to stop");
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
//!
//! THREE D-Bus object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
//! - `/org/opdbus/rovs/proxy`    → interface `org.opdbus.rovs.proxy`
//!
//! The daemon knows NOTHING about bridges, ports, or containers on the jsonrpc/openflow
//! paths.  It only proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
//! Business logic lives in the consuming plugins.
//!
//! The `proxy` path provides the openvswitch proxy operations for container
//! network namespace management (attach/detach OVS internal ports).

use anyhow::{Context, Result};
use rovs_ovsdb::Client;
use rovs_transport::Address;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info, warn};
use zbus::interface;

// ── Shared daemon state ───────────────────────────────────────────────────────

/// Global state shared by both D-Bus objects.
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// OVS Unix-domain socket path.
    pub socket_path: String,
    /// OpenFlow connections: conn_id → VConn.
    pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
    /// Monotonic connection handle allocator.
    pub next_of_id: Arc<Mutex<u64>>,
}

impl DaemonState {
    pub fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
            of_conns: Arc::new(Mutex::new(HashMap::new())),
            next_of_id: Arc::new(Mutex::new(1)),
        }
    }

    /// Get or create the persistent OVSDB client.
    pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;
        if guard.is_none() {
            let client = Client::connect(&format!("unix:{}", self.socket_path))
                .await
                .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
            info!("OVSDB client connected to {}", self.socket_path);
            *guard = Some(client);
        }
        Ok(guard)
    }

    /// Allocate a new OpenFlow connection handle id.
    pub async fn alloc_of_id(&self) -> u64 {
        let mut n = self.next_of_id.lock().await;
        let id = *n;
        *n += 1;
        id
    }
}

// ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────

/// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
pub struct JsonRpcService {
    state: DaemonState,
}

impl JsonRpcService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.jsonrpc")]
impl JsonRpcService {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` — JSON-RPC method name (always `"transact"` for OVSDB).
    /// `params_json` — JSON-encoded params array (e.g. `["Open_vSwitch", {op:...}]`).
    /// Returns JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> String {
        debug!(
            "jsonrpc.transact method={} params_len={}",
            method,
            params_json.len()
        );

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        // Parse params as serde_json::Value array.
        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        // We use the rovs_ovsdb::Client::transact_raw or similar.
        // Since rovs_ovsdb::Client exposes `transact(Value) -> Result<Value>`,
        // we forward directly.
        match client.transact(params).await {
            Ok(result) => match serde_json::to_string(&result) {
                Ok(s) => s,
                Err(e) => json_error(&format!("serialize result failed: {}", e)),
            },
            Err(e) => json_error(&format!("transact failed: {}", e)),
        }
    }

    /// One-way notify (fire-and-forget).
    async fn notify(&self, _method: &str, _params_json: &str) {
        // rovs-jsonrpc notify support — placeholder; most callers use transact.
        debug!("jsonrpc.notify (passthrough stub)");
    }

    /// Return next JSON-RPC request id (monotonic counter).
    async fn next_id(&self) -> u64 {
        // Simplistic id counter.  In full rovs-jsonrpc this is per-connection.
        1
    }

    /// Send raw JSON-RPC message string, return response string.
    async fn send_message(&self, msg: &str) -> String {
        debug!("jsonrpc.send_message len={}", msg.len());
        match serde_json::from_str::<serde_json::Value>(msg) {
            Ok(req) => {
                let mut guard = match self.state.get_ovsdb().await {
                    Ok(g) => g,
                    Err(e) => return json_error(&format!("connect failed: {}", e)),
                };
                let client = match guard.as_mut() {
                    Some(c) => c,
                    None => return json_error("client unavailable"),
                };
                match client.transact(req).await {
                    Ok(r) => {
                        serde_json::to_string(&r).unwrap_or_else(|e| json_error(&e.to_string()))
                    }
                    Err(e) => json_error(&e.to_string()),
                }
            }
            Err(e) => json_error(&format!("invalid JSON: {}", e)),
        }
    }

    /// Receive raw JSON-RPC message string.
    async fn recv_message(&self) -> String {
        // rovs-jsonrpc recv is async-stream oriented; stub for now.
        String::new()
    }

    /// Poll pending notifications.
    async fn has_pending_notifications(&self) -> bool {
        false
    }

    /// Count pending notifications.
    async fn pending_notification_count(&self) -> u64 {
        0
    }

    /// Pop one notification.
    async fn pop_notification(&self) -> String {
        String::new()
    }

    /// Drain all notifications.
    async fn drain_notifications(&self) -> String {
        "[]".to_string()
    }

    /// Open a new named stream / monitor.
    async fn new_stream(&self, stream: &str) -> String {
        debug!("jsonrpc.new_stream stream={}", stream);
        format!("{{\"stream\":\"{}\"}}", stream)
    }

    /// Daemon + connection status JSON.
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();
        format!(
            "{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected,
            self.state.socket_path,
            env!("CARGO_PKG_VERSION")
        )
    }
}

fn json_error(msg: &str) -> String {
    serde_json::json!({"error": msg}).to_string()
}

// ── OpenFlow object (/org/opdbus/rovs/openflow) ─────────────────────────────

/// D-Bus service proxying raw `rovs-openflow` primitives via `rovs_transport::Address`
/// and `rovs_openflow::VConn`.
pub struct OpenFlowService {
    state: DaemonState,
}

impl OpenFlowService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.openflow")]
impl OpenFlowService {
    /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
    ///
    /// `addr` is parsed by `rovs_transport::Address::from_str` which supports:
    /// - `unix:/path/to/socket`
    /// - `tcp:host:port`
    /// - `ssl:host:port`
    ///
    /// Returns JSON `{"conn_id":N}` or `{"error":"..."}`.
    async fn connect(&self, addr: &str) -> String {
        debug!("openflow.connect addr={}", addr);

        let address = match addr.parse::<Address>() {
            Ok(a) => a,
            Err(e) => return json_error(&format!("bad address: {}", e)),
        };

        match rovs_openflow::VConn::connect(&address).await {
            Ok(vconn) => {
                let id = self.state.alloc_of_id().await;
                self.state.of_conns.lock().await.insert(id, vconn);
                serde_json::json!({"conn_id": id}).to_string()
            }
            Err(e) => json_error(&format!("connect failed: {}", e)),
        }
    }

    /// Return negotiated OpenFlow version JSON.
    async fn version(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => {
                let ver = vconn.version();
                serde_json::json!({"version": format!("{:?}", ver)}).to_string()
            }
            None => json_error("unknown conn_id"),
        }
    }

    async fn send_flow(&self, conn_id: u64, flow_json: &str) -> String {
        debug!(
            "openflow.send_flow conn_id={} len={}",
            conn_id,
            flow_json.len()
        );
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send flow_mod + barrier.
    async fn send_flow_sync(&self, conn_id: u64, flow_json: &str) -> String {
        debug!("openflow.send_flow_sync conn_id={}", conn_id);
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow_sync(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow_sync failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send an echo request and wait for the echo reply.
    async fn echo(&self, conn_id: u64) -> String {
        debug!("openflow.echo conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.echo().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("echo failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Send a barrier request and wait for the barrier reply.
    async fn barrier(&self, conn_id: u64) -> String {
        debug!("openflow.barrier conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.barrier().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("barrier failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Dump all flows from the switch.  Returns a JSON array string per flow.
    async fn dump_flows(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.dump_flows conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.dump_flows().await {
                Ok(entries) => entries.iter().map(flow_stats_to_json).collect(),
                Err(e) => vec![json_error(&format!("dump_flows failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Dump flows matching a filter.  `request_json` is a placeholder.
    async fn dump_flows_filtered(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.dump_flows_filtered conn_id={}", conn_id);
        // TODO: deserialize FlowStatsRequest from JSON, then call vconn.dump_flows_filtered(req)
        self.dump_flows(conn_id).await
    }

    /// Block until a PacketIn message arrives.
    /// Returns JSON with buffer_id, in_port, reason, table_id, cookie, data (hex).
    async fn recv_packet_in(&self, conn_id: u64) -> String {
        debug!("openflow.recv_packet_in conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_packet_in().await {
                Ok(pkt) => packet_in_to_json(&pkt),
                Err(e) => json_error(&format!("recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Non-blocking try-receive PacketIn.
    async fn try_recv_packet_in(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.try_recv_packet_in().await {
                Ok(Some(pkt)) => packet_in_to_json(&pkt),
                Ok(None) => String::new(),
                Err(e) => json_error(&format!("try_recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Start flow monitor.  `request_json` is a placeholder.
    async fn monitor_flows(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.monitor_flows conn_id={}", conn_id);
        // TODO: deserialize FlowMonitorRequest from JSON
        Vec::new()
    }

    /// Block until flow updates arrive.
    async fn recv_flow_updates(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.recv_flow_updates conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_flow_updates().await {
                Ok(updates) => updates.iter().map(flow_update_to_json).collect(),
                Err(e) => vec![json_error(&format!("recv_flow_updates failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Send a packet_out.  `packet_out_json` is a placeholder.
    async fn send_packet_out(&self, conn_id: u64, _packet_out_json: &str) -> String {
        debug!("openflow.send_packet_out conn_id={}", conn_id);
        // TODO: deserialize PacketOut from JSON
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(_vconn) => {
                json_error("send_packet_out: JSON→PacketOut deserialiser not yet implemented")
            }
            None => json_error("unknown conn_id"),
        }
    }

    /// Controller status JSON.
    async fn status(&self) -> String {
        let count = self.state.of_conns.lock().await.len();
        format!(
            "{{\"connections\":{},\"version\":\"{}\"}}",
            count,
            env!("CARGO_PKG_VERSION")
        )
    }
}

// ── JSON serializers for rovs-openflow types ──────────────────────────────────

fn flow_stats_to_json(entry: &rovs_openflow::FlowStatsEntry) -> String {
    serde_json::json!({
        "table_id": entry.table_id,
        "duration_sec": entry.duration_sec,
        "duration_nsec": entry.duration_nsec,
        "priority": entry.priority,
        "idle_timeout": entry.idle_timeout,
        "hard_timeout": entry.hard_timeout,
        "flags": entry.flags,
        "cookie": entry.cookie,
        "packet_count": entry.packet_count,
        "byte_count": entry.byte_count,
        "match_fields_hex": bytes_to_hex(&entry.match_fields.encode()),
        "instructions_hex": bytes_to_hex(&entry.instructions),
    })
    .to_string()
}

fn packet_in_to_json(pkt: &rovs_openflow::PacketIn) -> String {
    serde_json::json!({
        "buffer_id": pkt.buffer_id,
        "total_len": pkt.total_len,
        "reason": format!("{:?}", pkt.reason),
        "table_id": pkt.table_id,
        "cookie": pkt.cookie,
        "match_fields_hex": bytes_to_hex(&pkt.match_fields.encode()),
        "data_hex": bytes_to_hex(&pkt.data),
    })
    .to_string()
}

fn flow_update_to_json(update: &rovs_openflow::FlowUpdate) -> String {
    match update {
        rovs_openflow::FlowUpdate::Full(full) => serde_json::json!({
            "type": "Full",
            "event": format!("{:?}", full.event),
            "reason": full.reason,
            "priority": full.priority,
            "idle_timeout": full.idle_timeout,
            "hard_timeout": full.hard_timeout,
            "table_id": full.table_id,
            "cookie": full.cookie,
            "match_fields_hex": bytes_to_hex(&full.match_fields.encode()),
            "actions_hex": bytes_to_hex(&full.actions),
        }),
        rovs_openflow::FlowUpdate::Abbrev { xid } => serde_json::json!({
            "type": "Abbrev",
            "xid": xid,
        }),
    }
    .to_string()
}

/// Simple hex encoder (avoids pulling in the `hex` crate).
fn bytes_to_hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(HEX[(b >> 4) as usize] as char);
        s.push(HEX[(b & 0xF) as usize] as char);
    }
    s
}

#[derive(serde::Deserialize, Debug)]
#[allow(dead_code)]
pub struct JsonFlowEntry {
    pub table: u8,
    pub priority: u16,
    pub match_fields: std::collections::HashMap<String, String>,
    pub actions: Vec<JsonFlowAction>,
    pub cookie: Option<u64>,
    #[serde(default)]
    pub idle_timeout: u16,
    #[serde(default)]
    pub hard_timeout: u16,
}

#[derive(serde::Deserialize, Debug)]
#[serde(tag = "type", rename_all = "snake_case")]
#[allow(dead_code)]
pub enum JsonFlowAction {
    Output { port: String },
    LoadRegister { register: u8, value: u64 },
    Resubmit { table: u8 },
    SetField { field: String, value: String },
    Drop,
    Normal,
    Controller { max_len: Option<u16> },
    ArpResponder { mac: String, ip: String },
}

fn parse_json_flow(flow_json: &str) -> Result<rovs_openflow::Flow> {
    let entry: JsonFlowEntry =
        serde_json::from_str(flow_json).context("invalid JsonFlowEntry format")?;

    let mut m = rovs_openflow::Match::new();
    for (k, v) in entry.match_fields {
        match k.as_str() {
            "in_port" => {
                if let Ok(port) = v.parse::<u32>() {
                    m = m.in_port(port);
                }
            }
            "dl_type" => {
                let eth_type = if v.starts_with("0x") {
                    u16::from_str_radix(v.trim_start_matches("0x"), 16).unwrap_or(0)
                } else {
                    v.parse().unwrap_or(0)
                };
                m = m.eth_type(eth_type);
            }
            "dl_vlan" => {
                if let Ok(vlan) = v.parse::<u16>() {
                    m = m.vlan_vid(vlan);
                }
            }
            // Add other matches here as required
            _ => {
                tracing::warn!("Unsupported match field in JSON->Flow map: {}={}", k, v);
            }
        }
    }

    let mut action_list = rovs_openflow::ActionList::new();
    for action in entry.actions {
        match action {
            JsonFlowAction::Output { port } => {
                if port.eq_ignore_ascii_case("LOCAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Local);
                } else if port.eq_ignore_ascii_case("NORMAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Normal);
                } else if let Ok(p) = port.parse::<u32>() {
                    action_list = action_list.output(rovs_openflow::OutputPort::Port(p));
                } else {
                    tracing::warn!("Invalid numeric port output: {}", port);
                }
            }
            JsonFlowAction::Normal => {
                action_list = action_list.output(rovs_openflow::OutputPort::Normal);
            }
            JsonFlowAction::Drop => {}
            // Other actions could be mapped here.
            _ => {
                tracing::warn!("Unsupported JSON->Flow action: {:?}", action);
            }
        }
    }

    let mut flow = rovs_openflow::Flow::add()
        .priority(entry.priority)
        .match_fields(m)
        .actions(action_list)
        .idle_timeout(entry.idle_timeout)
        .hard_timeout(entry.hard_timeout);

    if let Some(c) = entry.cookie {
        flow = flow.cookie(c);
    }

    // Some rovs_openflow Flow builders support .table_id(u8), we will skip it for now
    // unless explicitly supported by the FlowAddBuilder. (Usually table_id=0 by default).

    Ok(flow)
}

// ── OVS Proxy object (/org/opdbus/rovs/proxy) ─────────────────────────────────

/// D-Bus service for the openvswitch proxy: attach/detach OVS internal ports
/// to container network namespaces.
pub struct ProxyService {
    state: DaemonState,
}

impl ProxyService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.proxy")]
impl ProxyService {
    /// Create an OVS internal port on a bridge, move it into a container's
    /// netns, rename it, and bring it up.
    ///
    /// `params_json` — JSON: {"port_name":"..","bridge":"..","target_pid":N,"iface_name":"..","ip_addrs":[".."]}
    /// Returns JSON: {"success":bool,"message":"..","iface_name":".."}
    async fn attach_port(&self, params_json: &str) -> String {
        debug!("proxy.attach_port params_len={}", params_json.len());

        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        let port_name = match params.get("port_name").and_then(|v| v.as_str()) {
            Some(n) => n.to_string(),
            None => return json_error("missing port_name"),
        };
        let bridge = match params.get("bridge").and_then(|v| v.as_str()) {
            Some(b) => b.to_string(),
            None => return json_error("missing bridge"),
        };
        // Resolve target_pid: either directly provided, or via instance_name lookup
        let target_pid = if let Some(pid) = params.get("target_pid").and_then(|v| v.as_u64()) {
            pid as u32
        } else if let Some(name) = params.get("instance_name").and_then(|v| v.as_str()) {
            // Resolve incus instance name to host PID
            match crate::container::pid_from_instance_name(name) {
                Ok(pid) => {
                    info!("resolved instance_name {} to host PID {}", name, pid);
                    pid
                }
                Err(e) => {
                    return serde_json::json!({
                        "success": false,
                        "message": format!("instance_name {} lookup failed: {}", name, e),
                        "iface_name": ""
                    })
                    .to_string();
                }
            }
        } else {
            return json_error("missing target_pid or instance_name");
        };
        let iface_name = params
            .get("iface_name")
            .and_then(|v| v.as_str())
            .unwrap_or(&port_name)
            .to_string();
        let ip_addrs: Vec<String> = params
            .get("ip_addrs")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        let gateway: Option<String> = params
            .get("gateway")
            .and_then(|v| v.as_str())
            .map(String::from);
        let routes: Vec<String> = params
            .get("routes")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();

        // Step 1: Create OVS internal port via OVSDB transact
        let iface_row = serde_json::json!({ "name": &port_name, "type": "internal" });
        let add_ops = serde_json::json!([
            {
                "op": "insert",
                "table": "Interface",
                "row": iface_row,
                "uuid-name": "new_iface"
            },
            {
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": &port_name,
                    "interfaces": ["set", [["named-uuid", "new_iface"]]]
                },
                "uuid-name": "new_port"
            },
            {
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", &bridge]],
                "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
            },
        ]);

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        match client.transact(add_ops).await {
            Ok(_) => info!("OVSDB: internal port {} created on {}", port_name, bridge),
            Err(e) => {
                return serde_json::json!({
                    "success": false,
                    "message": format!("OVSDB add_port failed: {}", e),
                    "iface_name": ""
                })
                .to_string();
            }
        }
        drop(guard);

        // Step 2: Bring up on host, move to netns, rename, bring up
        // These rtnetlink operations use block_on internally, so they MUST run
        // in spawn_blocking to avoid deadlocking the tokio runtime.
        let port_name_cb = port_name.clone();
        let iface_name_cb = iface_name.clone();
        let ip_addrs_cb = ip_addrs.clone();
        let gateway_cb = gateway.clone();
        let routes_cb = routes.clone();
        let netns_result = tokio::task::spawn_blocking(move || -> Result<String> {
            if let Err(e) = crate::netns::set_link_up_rtnetlink(&port_name_cb) {
                return Ok(serde_json::json!({
                    "success": false,
                    "message": format!("bring up on host failed: {}", e),
                    "iface_name": ""
                })
                .to_string());
            }

            if let Err(e) = crate::netns::move_interface_to_netns(&port_name_cb, target_pid) {
                return Ok(serde_json::json!({
                    "success": false,
                    "message": format!("move to netns failed: {}", e),
                    "iface_name": ""
                })
                .to_string());
            }

            if port_name_cb != iface_name_cb {
                if let Err(e) =
                    crate::netns::rename_in_netns(&port_name_cb, &iface_name_cb, target_pid)
                {
                    return Ok(serde_json::json!({
                        "success": false,
                        "message": format!("rename in netns failed: {}", e),
                        "iface_name": iface_name_cb
                    })
                    .to_string());
                }
            }

            let _ = crate::netns::set_link_up_in_netns(&iface_name_cb, target_pid);

            // Step 3: Add IP addresses
            for addr in &ip_addrs_cb {
                match crate::netns::add_addr_in_netns(&iface_name_cb, addr, target_pid) {
                    Ok(_) => info!("proxy: added addr {} to {}", addr, iface_name_cb),
                    Err(e) => warn!("proxy: failed to add addr {} to {}: {}", addr, iface_name_cb, e),
                }
            }

            // Step 4: Add default route via gateway
            if let Some(gw) = &gateway_cb {
                match crate::netns::add_route_in_netns(&iface_name_cb, "default", gw, target_pid) {
                    Ok(_) => info!("proxy: added default route via {}", gw),
                    Err(e) => warn!("proxy: failed to add default route via {}: {}", gw, e),
                }
            }

            // Step 5: Add extra routes
            for route in &routes_cb {
                // Format: "dest via gateway" e.g. "10.0.0.1 via 10.200.0.2"
                let parts: Vec<&str> = route.splitn(2, " via ").collect();
                if parts.len() == 2 {
                    match crate::netns::add_route_in_netns(
                        &iface_name_cb,
                        parts[0],
                        parts[1],
                        target_pid,
                    ) {
                        Ok(_) => info!("proxy: added route {} via {}", parts[0], parts[1]),
                        Err(e) => warn!("proxy: failed to add route {}: {}", route, e),
                    }
                }
            }

            Ok(serde_json::json!({
                "success": true,
                "message": format!("Port {} attached to PID {} as {}", port_name_cb, target_pid, iface_name_cb),
                "iface_name": iface_name_cb
            })
            .to_string())
        })
        .await;

        match netns_result {
            Ok(Ok(result_json)) => result_json,
            Ok(Err(e)) => serde_json::json!({
                "success": false,
                "message": format!("netns operation error: {}", e),
                "iface_name": iface_name
            })
            .to_string(),
            Err(e) => serde_json::json!({
                "success": false,
                "message": format!("spawn_blocking panic: {}", e),
                "iface_name": iface_name
            })
            .to_string(),
        }
    }

    /// Remove an OVS port from a bridge (works regardless of which netns it's in).
    ///
    /// `params_json` — JSON: {"port_name":"..","bridge":".."}
    /// Returns JSON: {"success":bool,"message":".."}
    async fn detach_port(&self, params_json: &str) -> String {
        debug!("proxy.detach_port params_len={}", params_json.len());

        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        let port_name = match params.get("port_name").and_then(|v| v.as_str()) {
            Some(n) => n.to_string(),
            None => return json_error("missing port_name"),
        };
        let bridge = match params.get("bridge").and_then(|v| v.as_str()) {
            Some(b) => b.to_string(),
            None => return json_error("missing bridge"),
        };

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        let del_ops = serde_json::json!([
            {
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", &bridge]],
                "mutations": [["ports", "delete", ["name", &port_name]]]
            },
            {
                "op": "delete",
                "table": "Port",
                "where": [["name", "==", &port_name]]
            },
            {
                "op": "delete",
                "table": "Interface",
                "where": [["name", "==", &port_name]]
            },
        ]);

        match client.transact(del_ops).await {
            Ok(_) => serde_json::json!({
                "success": true,
                "message": format!("Port {} detached from {}", port_name, bridge)
            })
            .to_string(),
            Err(e) => serde_json::json!({
                "success": false,
                "message": format!("OVSDB remove failed: {}", e)
            })
            .to_string(),
        }
    }

    /// Bring up the loopback interface (lo) inside a container's netns.
    ///
    /// OCI containers with no NIC device boot with lo DOWN, preventing
    /// services from binding to 127.0.0.1. This method enters the
    /// container's netns and runs `ip link set lo up`.
    ///
    /// `params_json` — JSON: {"instance_name":".."} or {"target_pid":N}
    /// Returns JSON: {"success":bool,"message":"..","target_pid":N}
    async fn bring_up_loopback(&self, params_json: &str) -> String {
        debug!("proxy.bring_up_loopback params_len={}", params_json.len());

        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        let target_pid = if let Some(pid) = params.get("target_pid").and_then(|v| v.as_u64()) {
            pid as u32
        } else if let Some(name) = params.get("instance_name").and_then(|v| v.as_str()) {
            match crate::container::pid_from_instance_name(name) {
                Ok(pid) => pid,
                Err(e) => {
                    return serde_json::json!({
                        "success": false,
                        "message": format!("instance_name {} lookup failed: {}", name, e),
                        "target_pid": 0
                    })
                    .to_string();
                }
            }
        } else {
            return json_error("missing target_pid or instance_name");
        };

        let pid_cb = target_pid;
        let result =
            tokio::task::spawn_blocking(move || crate::netns::bring_up_loopback(pid_cb)).await;

        match result {
            Ok(Ok(_)) => serde_json::json!({
                "success": true,
                "message": format!("lo brought up inside PID {}", target_pid),
                "target_pid": target_pid
            })
            .to_string(),
            Ok(Err(e)) => serde_json::json!({
                "success": false,
                "message": format!("lo bring-up failed: {}", e),
                "target_pid": target_pid
            })
            .to_string(),
            Err(e) => serde_json::json!({
                "success": false,
                "message": format!("spawn_blocking panic: {}", e),
                "target_pid": target_pid
            })
            .to_string(),
        }
    }

    /// Schema-driven container network initialization.
    ///
    /// Performs all host-side bootstrap operations that containers need
    /// before their services can start: loopback bring-up, OVS port attach,
    /// route configuration, etc.
    ///
    /// `params_json` — JSON: {
    ///   "instance_name": "..",
    ///   "loopback_required": true,
    ///   "port_config": { .. } // optional, same as attach_port params
    /// }
    /// Returns JSON: {"success":bool,"instance_name":"..","target_pid":N,"steps":[..]}
    async fn container_init(&self, params_json: &str) -> String {
        debug!("proxy.container_init params_len={}", params_json.len());

        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        let instance_name = match params.get("instance_name").and_then(|v| v.as_str()) {
            Some(n) => n.to_string(),
            None => return json_error("missing instance_name"),
        };
        let loopback_required = params
            .get("loopback_required")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let port_config = params.get("port_config").cloned();

        let instance_name_cb = instance_name.clone();
        let result = tokio::task::spawn_blocking(move || {
            crate::netns::container_netns_init(
                &instance_name_cb,
                loopback_required,
                port_config.as_ref(),
            )
        })
        .await;

        match result {
            Ok(Ok(result_json)) => result_json.to_string(),
            Ok(Err(e)) => serde_json::json!({
                "success": false,
                "instance_name": instance_name,
                "message": format!("container_init error: {}", e)
            })
            .to_string(),
            Err(e) => serde_json::json!({
                "success": false,
                "instance_name": instance_name,
                "message": format!("spawn_blocking panic: {}", e)
            })
            .to_string(),
        }
    }
}

//! Schema-Driven Dynamic gRPC Router
//!
//! Reads the live schema catalog from `/dev/shm/live-schema.json`.
//! Dynamically routes incoming gRPC calls to their corresponding D-Bus objects
//! at `/org/opdbus/v1/plugins/<plugin>`.
//!
//! Every plugin defined in the schema catalog is automatically exposed as a
//! gRPC-callable service through the bridge. Unknown methods are rejected by
//! schema validation — no hand-rolling required.
//!
//! ## Schema Access Path
//!
//! **Combined monolith:** `/dev/shm/live-schema.json` — authoritative catalog of all plugins.
//!
//! The manifest hash is read, never re-computed. Consumers trust the manifest.

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::Arc;

use jsonschema::Validator;
use serde_json::Value as JsonValue;
use tokio::sync::RwLock;
use tracing::{debug, info, warn};

// Import capability grants loader for bridge-layer enforcement (VAL-ENFORCE-002).
use crate::interceptor::load_capability_grants;
use zbus::{Connection, Proxy};

use crate::schema_engine::SchemaEngine;

use op_plugins::canonical::{self, BASE_SERVICE_NAME};

/// The combined monolith catalog in shared memory.
const LIVE_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

/// The producer's catalog manifest in shared memory. Carries the Blake3
/// `catalog_hash` of the schema catalog (`{ "catalog_hash": "<hex>" }`).
/// The bridge reads this hash, never re-computes it.
const MANIFEST_PATH: &str = "/dev/shm/opdbus/.manifest.json";

/// A schema-derived route entry for a plugin.
#[derive(Debug, Clone)]
pub struct PluginRoute {
    /// Plugin identifier (e.g. "unix_socket", "wireguard").
    pub plugin_id: String,
    /// Canonical D-Bus object path: `/org/opdbus/v1/plugins/<plugin_id>`.
    pub dbus_path: String,
    /// Canonical D-Bus destination (bus name): `org.opdbus.v1`.
    pub dbus_destination: String,
    /// Canonical D-Bus interface: `org.opdbus.v1.Plugin.<PluginName>`.
    pub dbus_interface: String,
    /// Methods declared in the schema (name → `MethodDecl` JSON).
    pub methods: HashMap<String, JsonValue>,
    /// Signals declared in the schema (each entry a `SignalDecl` JSON object).
    pub signals: Vec<JsonValue>,
    /// Properties declared in the schema (name → field schema).
    pub properties: HashMap<String, JsonValue>,
}

/// The dynamic schema router that maps plugin_id → D-Bus route.
pub struct SchemaRouter {
    /// Plugin routes keyed by plugin_id.
    routes: Arc<RwLock<HashMap<String, PluginRoute>>>,
    /// D-Bus system connection (shared with SchemaEngine).
    dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
    /// Combined monolith catalog path (default [`LIVE_SCHEMA_PATH`]).
    monolith_path: PathBuf,
    /// Present-state directory used to derive read-only child objects.
    state_dir: PathBuf,
    /// Producer manifest path (default [`MANIFEST_PATH`]).
    manifest_path: PathBuf,
    /// Last-seen `catalog_hash` read from the manifest. Compared on each
    /// inbound connection; a change triggers a reload. `None` when no manifest
    /// has been observed yet.
    cached_hash: Arc<RwLock<Option<String>>>,
    /// The SchemaEngine used for real method dispatch (Requirement 5).
    /// `None` in unit tests that do not exercise the dispatch path.
    engine: Option<Arc<SchemaEngine>>,
    /// Optional projection hook invoked after object registration to publish
    /// the read-only Zeroclaw route/provider sub-object tree (Phase 1b). Push
    /// only — invoked from the registration cycle, never on a timer.
    projection_hook: Option<Arc<dyn crate::zeroclaw_projection::SchemaProjectionHook>>,
    /// Child object paths currently registered by this router.
    child_objects: Arc<RwLock<HashSet<String>>>,
}

impl SchemaRouter {
    /// Create a new SchemaRouter and load routes from both schema sources.
    ///
    /// Loads synchronously at startup — the schema in /dev/shm is authoritative
    /// present-state and is always available. No polling or watchers.
    ///
    /// The last-seen `catalog_hash` is read from the manifest at construction
    /// so the first inbound connection only reloads if the catalog actually
    /// changed since startup.
    pub fn new(dbus_connection: Arc<tokio::sync::OnceCell<Connection>>) -> Self {
        Self::with_paths(
            dbus_connection,
            PathBuf::from(LIVE_SCHEMA_PATH),
            PathBuf::from(DEFAULT_SHM_STATE_DIR),
            PathBuf::from(MANIFEST_PATH),
        )
    }

    /// Create a new SchemaRouter wired to a SchemaEngine for real dispatch.
    ///
    /// This is the production constructor: the bridge passes its
    /// `Arc<SchemaEngine>` so every registered `SchemaBackedInterface` can
    /// dispatch method calls through `SchemaEngine::dispatch_method_call`
    /// (Requirement 5 / VAL-DISPATCH-001).
    pub fn with_engine(
        dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
        engine: Arc<SchemaEngine>,
    ) -> Self {
        let mut router = Self::new(dbus_connection);
        router.engine = Some(engine);
        router
    }

    /// Create a SchemaRouter with explicit SHM paths.
    ///
    /// In production, use [`new`](Self::new) which targets the canonical
    /// `/dev/shm` layout. Tests supply temporary paths to exercise the
    /// manifest-hash change-detection path without touching live SHM.
    pub fn with_paths(
        dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
        monolith_path: PathBuf,
        state_dir: PathBuf,
        manifest_path: PathBuf,
    ) -> Self {
        let routes = Self::load_routes_from(&monolith_path);
        let cached_hash = Self::read_manifest_hash_at(&manifest_path);
        info!(
            count = routes.len(),
            "SchemaRouter initialized from schema catalog"
        );
        Self {
            routes: Arc::new(RwLock::new(routes)),
            dbus_connection,
            monolith_path,
            state_dir,
            manifest_path,
            cached_hash: Arc::new(RwLock::new(cached_hash)),
            engine: None,
            projection_hook: None,
            child_objects: Arc::new(RwLock::new(HashSet::new())),
        }
    }

    /// Register a projection hook that publishes the read-only Zeroclaw
    /// route/provider sub-object tree after each object-registration cycle.
    pub fn set_projection_hook(
        &mut self,
        hook: Arc<dyn crate::zeroclaw_projection::SchemaProjectionHook>,
    ) {
        self.projection_hook = Some(hook);
    }

    /// Register D-Bus objects for all plugins in the catalog.
    ///
    /// This makes the bridge the authoritative creator of the D-Bus objects
    /// defined in the schema.
    pub async fn register_objects(&self) -> anyhow::Result<()> {
        let conn = self
            .dbus_connection
            .get()
            .ok_or_else(|| anyhow::anyhow!("D-Bus connection not initialized"))?;

        let routes = self.routes.read().await;
        for (plugin_id, route) in routes.iter() {
            let interface = SchemaBackedInterface::with_engine(
                plugin_id.clone(),
                route.clone(),
                self.engine.clone(),
            );
            let path = route.dbus_path.clone();

            debug!(plugin_id, path, "Registering authoritative D-Bus object");
            if let Err(e) = conn.object_server().at(path.as_str(), interface).await {
                debug!(plugin_id, path, error = %e, "Failed to register D-Bus object (likely already registered)");
            }
        }
        drop(routes);

        self.sync_child_objects().await?;
        Ok(())
    }

    /// Register read-only child objects for every plugin from present-state.
    ///
    /// Child paths are derived from nested objects/arrays in
    /// `/dev/shm/opdbus/state/<plugin>.json`. The router stores only mounted
    /// paths for lifecycle; every child property read re-reads SHM directly.
    async fn sync_child_objects(&self) -> anyhow::Result<()> {
        let conn = self
            .dbus_connection
            .get()
            .ok_or_else(|| anyhow::anyhow!("D-Bus connection not initialized"))?;

        let routes = self.routes.read().await;
        let desired = routes
            .iter()
            .flat_map(|(plugin_id, route)| {
                derive_child_paths(plugin_id, &self.state_dir, &route.properties)
                    .into_iter()
                    .map(|segments| {
                        (
                            build_child_path(plugin_id, &segments),
                            plugin_id.clone(),
                            segments,
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        drop(routes);

        let desired_paths = desired
            .iter()
            .map(|(path, _, _)| path.clone())
            .collect::<HashSet<_>>();

        let mut current = self.child_objects.write().await;
        for stale in current
            .iter()
            .filter(|path| !desired_paths.contains(*path))
            .cloned()
            .collect::<Vec<_>>()
        {
            conn.object_server()
                .remove::<SchemaChildInterface, _>(stale.as_str())
                .await?;
            current.remove(&stale);
            debug!(
                path = stale,
                "unregistered stale schema-derived child object"
            );
        }

        for (path, plugin_id, segments) in desired {
            if current.contains(&path) {
                continue;
            }
            let child = SchemaChildInterface::new(plugin_id, segments, self.state_dir.clone());
            conn.object_server().at(path.as_str(), child).await?;
            current.insert(path.clone());
            debug!(path, "registered schema-derived child object");
        }

        Ok(())
    }

    /// Reload routes and re-register objects.
    pub async fn reload(&self) -> anyhow::Result<()> {
        let count = self.reload_routes_only().await;
        info!(count, "SchemaRouter reloaded plugin routes");
        self.register_objects().await
    }

    /// Reload routes from the SHM catalog into the in-memory route table
    /// without touching the D-Bus object server. Returns the route count.
    ///
    /// This is a direct read of the live schema catalog — no polling, no watchers.
    async fn reload_routes_only(&self) -> usize {
        let routes = Self::load_routes_from(&self.monolith_path);
        let count = routes.len();
        let mut w = self.routes.write().await;
        *w = routes;
        count
    }

    /// Reload the SHM catalog and re-register D-Bus objects **iff** the
    /// producer's `catalog_hash` changed since the last observation.
    ///
    /// This is the no-polling change-detection hook: it is invoked on inbound
    /// connection arrival (before dispatching a method call), never on a timer.
    /// The current `catalog_hash` is read directly from `.manifest.json` and
    /// compared to the cached value. On a change, routes are reloaded from SHM,
    /// the cached hash is advanced, and changed objects are re-registered on the
    /// bus without restarting the bridge. Returns `true` when a reload occurred.
    ///
    /// The hash is read, never re-computed — the producer is the sole authority
    /// for `catalog_hash`.
    pub async fn refresh_if_changed(&self) -> anyhow::Result<bool> {
        let current = self.read_manifest_hash();
        let changed = {
            let cached = self.cached_hash.read().await;
            match (cached.as_deref(), current.as_deref()) {
                // No manifest present → no hash to compare against; do nothing.
                (_, None) => false,
                // First observed hash, or a differing hash → reload.
                (None, Some(_)) => true,
                (Some(cached_hash), Some(current_hash)) => cached_hash != current_hash,
            }
        };

        if !changed {
            return Ok(false);
        }

        let count = self.reload_routes_only().await;
        {
            let mut w = self.cached_hash.write().await;
            *w = current;
        }
        info!(
            count,
            "manifest catalog_hash changed on inbound — reloaded SHM, re-registering objects"
        );

        // Re-register the (possibly changed) object set on the bus. Skipped when
        // the D-Bus connection is not yet initialized (e.g. unit tests), so the
        // route reload and hash advance remain observable without a live bus.
        if self.dbus_connection.get().is_some() {
            self.register_objects().await?;
        }
        Ok(true)
    }

    /// The currently cached `catalog_hash`, or `None` if no manifest has been
    /// observed.
    pub async fn cached_catalog_hash(&self) -> Option<String> {
        self.cached_hash.read().await.clone()
    }

    /// List all currently routable plugin IDs.
    pub async fn list_plugin_ids(&self) -> Vec<String> {
        let r = self.routes.read().await;
        r.keys().cloned().collect()
    }

    /// Get the route for a specific plugin.
    pub async fn get_route(&self, plugin_id: &str) -> Option<PluginRoute> {
        let r = self.routes.read().await;
        r.get(plugin_id).cloned()
    }

    /// Call a method on a plugin via its schema-derived D-Bus route.
    pub async fn call_method(
        &self,
        plugin_id: &str,
        method_name: &str,
        json_args: &str,
    ) -> Result<String, SchemaRouterError> {
        let route = self
            .get_route(plugin_id)
            .await
            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;

        if !route.methods.contains_key(method_name) {
            return Err(SchemaRouterError::MethodNotFound {
                plugin_id: plugin_id.to_string(),
                method: method_name.to_string(),
                available: route.methods.keys().cloned().collect(),
            });
        }

        let conn = self
            .dbus_connection
            .get()
            .ok_or(SchemaRouterError::DbusUnavailable)?;

        let proxy = Proxy::new(
            conn,
            route.dbus_destination.as_str(),
            route.dbus_path.as_str(),
            route.dbus_interface.as_str(),
        )
        .await
        .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let result: String = proxy
            .call(method_name, &(json_args.to_string(),))
            .await
            .map_err(|e| SchemaRouterError::DbusCallFailed {
                method: method_name.to_string(),
                error: e.to_string(),
            })?;

        Ok(result)
    }

    /// Get a property from a plugin via its schema-derived D-Bus route.
    pub async fn get_property(
        &self,
        plugin_id: &str,
        property_name: &str,
    ) -> Result<String, SchemaRouterError> {
        let route = self
            .get_route(plugin_id)
            .await
            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;

        if !route.properties.contains_key(property_name) {
            return Err(SchemaRouterError::PropertyNotFound {
                plugin_id: plugin_id.to_string(),
                property: property_name.to_string(),
                available: route.properties.keys().cloned().collect(),
            });
        }

        let conn = self
            .dbus_connection
            .get()
            .ok_or(SchemaRouterError::DbusUnavailable)?;

        let props = zbus::fdo::PropertiesProxy::builder(conn)
            .destination(route.dbus_destination.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
            .path(route.dbus_path.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
            .build()
            .await
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let iface = zbus::names::InterfaceName::try_from(route.dbus_interface.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let val: zbus::zvariant::OwnedValue =
            props.get(iface, property_name).await.map_err(|e| {
                SchemaRouterError::DbusCallFailed {
                    method: format!("Get({})", property_name),
                    error: e.to_string(),
                }
            })?;

        serde_json::to_string(&val)
            .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))
    }

    /// Set a property on a plugin via its schema-derived D-Bus route.
    pub async fn set_property(
        &self,
        plugin_id: &str,
        property_name: &str,
        json_value: &str,
    ) -> Result<(), SchemaRouterError> {
        let route = self
            .get_route(plugin_id)
            .await
            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;

        if !route.properties.contains_key(property_name) {
            return Err(SchemaRouterError::PropertyNotFound {
                plugin_id: plugin_id.to_string(),
                property: property_name.to_string(),
                available: route.properties.keys().cloned().collect(),
            });
        }

        let conn = self
            .dbus_connection
            .get()
            .ok_or(SchemaRouterError::DbusUnavailable)?;

        let props = zbus::fdo::PropertiesProxy::builder(conn)
            .destination(route.dbus_destination.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
            .path(route.dbus_path.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
            .build()
            .await
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let iface = zbus::names::InterfaceName::try_from(route.dbus_interface.as_str())
            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;

        let value: serde_json::Value = serde_json::from_str(json_value)
            .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))?;

        let zval = json_to_zvariant_value(&value)?;

        props.set(iface, property_name, zval).await.map_err(|e| {
            SchemaRouterError::DbusCallFailed {
                method: format!("Set({})", property_name),
                error: e.to_string(),
            }
        })?;

        Ok(())
    }

    // ── Private helpers ─────────────────────────────────────────────────────

    /// Reads the `catalog_hash` from this router's manifest path.
    fn read_manifest_hash(&self) -> Option<String> {
        Self::read_manifest_hash_at(&self.manifest_path)
    }

    /// Reads `{ "catalog_hash": "<hex>" }` from the manifest at `path`.
    ///
    /// Returns `None` if the file is absent, unparsable, or lacks a string
    /// `catalog_hash`. This is a direct synchronous SHM read — no polling.
    fn read_manifest_hash_at(path: &Path) -> Option<String> {
        let text = std::fs::read_to_string(path).ok()?;
        let value: JsonValue = serde_json::from_str(&text).ok()?;
        value
            .get("catalog_hash")
            .and_then(|h| h.as_str())
            .map(String::from)
    }

    /// Loads plugin routes from the combined monolith. If the monolith is
    /// unavailable or invalid, no routes are exposed.
    fn load_routes_from(monolith_path: &Path) -> HashMap<String, PluginRoute> {
        Self::load_from_monolith(monolith_path).unwrap_or_default()
    }

    fn load_from_monolith(path: &Path) -> Option<HashMap<String, PluginRoute>> {
        let bytes = std::fs::read(path).ok()?;
        let root: JsonValue = serde_json::from_slice(&bytes).ok()?;
        let catalog = root.as_object()?;

        let mut routes = HashMap::new();
        for (plugin_id, schema_value) in catalog {
            let schema = match schema_value {
                JsonValue::Array(arr) => arr.first()?,
                JsonValue::Object(_) => schema_value,
                _ => continue,
            };
            let route = Self::build_route(plugin_id, schema);
            routes.insert(plugin_id.clone(), route);
        }
        Some(routes)
    }

    fn build_route(plugin_id: &str, schema: &JsonValue) -> PluginRoute {
        let dbus_path = canonical::plugin_path(plugin_id);
        let dbus_destination = BASE_SERVICE_NAME.to_string();
        let dbus_interface = canonical::plugin_interface(plugin_id);
        let methods = Self::extract_methods(schema);
        let signals = Self::extract_signals(schema);
        let properties = Self::extract_properties(schema);
        PluginRoute {
            plugin_id: plugin_id.to_string(),
            dbus_path,
            dbus_destination,
            dbus_interface,
            methods,
            signals,
            properties,
        }
    }

    fn extract_methods(schema: &JsonValue) -> HashMap<String, JsonValue> {
        let mut methods = HashMap::new();
        if let Some(method_map) = schema.get("methods").and_then(|m| m.as_object()) {
            for (name, def) in method_map {
                methods.insert(name.clone(), def.clone());
            }
        }
        methods
    }

    /// Extracts the `signals` array from a plugin schema. Each entry is a
    /// `SignalDecl` JSON object (`name`, `payload`, `subid`). Absent or
    /// non-array `signals` yields an empty list.
    fn extract_signals(schema: &JsonValue) -> Vec<JsonValue> {
        schema
            .get("signals")
            .and_then(|s| s.as_array())
            .cloned()
            .unwrap_or_default()
    }

    fn extract_properties(schema: &JsonValue) -> HashMap<String, JsonValue> {
        let mut properties = HashMap::new();
        if let Some(props) = schema
            .get("fields")
            .or_else(|| schema.get("properties"))
            .and_then(|p| p.as_object())
        {
            for (name, def) in props {
                properties.insert(name.clone(), def.clone());
            }
        }
        properties
    }
}

/// Default SHM state directory: `/dev/shm/opdbus/state`.
const DEFAULT_SHM_STATE_DIR: &str = "/dev/shm/opdbus/state";

fn derive_child_paths(
    plugin_id: &str,
    state_dir: &Path,
    schema_fields: &HashMap<String, JsonValue>,
) -> Vec<Vec<String>> {
    let state = read_plugin_state(plugin_id, state_dir);
    let root = state.get("data").unwrap_or(&state);
    let mut paths = Vec::new();
    derive_child_paths_recursive(root, schema_fields, &mut Vec::new(), &mut paths);
    paths
}

fn derive_child_paths_recursive(
    state: &JsonValue,
    schema_fields: &HashMap<String, JsonValue>,
    current: &mut Vec<String>,
    paths: &mut Vec<Vec<String>>,
) {
    let Some(state_obj) = state.as_object() else {
        return;
    };

    for (field_name, field_schema) in schema_fields {
        if field_name.starts_with('_') {
            continue;
        }
        let Some(child) = state_obj.get(field_name) else {
            continue;
        };

        if let Some(nested_fields) = schema_object_fields(field_schema) {
            if child.is_object() {
                current.push(path_element(field_name));
                paths.push(current.clone());
                derive_child_paths_recursive(child, &nested_fields, current, paths);
                current.pop();
            }
            continue;
        }

        if let Some(item_fields) = schema_array_item_fields(field_schema) {
            let Some(items) = child.as_array() else {
                continue;
            };
            current.push(path_element(field_name));
            paths.push(current.clone());
            for (index, item) in items.iter().enumerate() {
                if item.is_object() {
                    let segment = ["id", "name", "label", "key", "path", "domain", "host"]
                        .iter()
                        .find_map(|field| item.get(*field).and_then(JsonValue::as_str))
                        .map(path_element)
                        .unwrap_or_else(|| index.to_string());
                    current.push(segment);
                    paths.push(current.clone());
                    derive_child_paths_recursive(item, &item_fields, current, paths);
                    current.pop();
                }
            }
            current.pop();
        }
    }
}

fn schema_object_fields(field_schema: &JsonValue) -> Option<HashMap<String, JsonValue>> {
    field_schema
        .get("field_type")?
        .get("object")?
        .as_object()
        .map(|fields| {
            fields
                .iter()
                .map(|(name, schema)| (name.clone(), schema.clone()))
                .collect()
        })
}

fn schema_array_item_fields(field_schema: &JsonValue) -> Option<HashMap<String, JsonValue>> {
    field_schema
        .get("field_type")?
        .get("array")?
        .get("object")?
        .as_object()
        .map(|fields| {
            fields
                .iter()
                .map(|(name, schema)| (name.clone(), schema.clone()))
                .collect()
        })
}

fn build_child_path(plugin_id: &str, segments: &[String]) -> String {
    let mut path = canonical::plugin_path(plugin_id);
    for segment in segments {
        path.push('/');
        path.push_str(&path_element(segment));
    }
    path
}

fn path_element(value: &str) -> String {
    let mut out = value
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect::<String>();
    if out.is_empty() {
        out.push('_');
    }
    if out
        .chars()
        .next()
        .map(|c| c.is_ascii_digit())
        .unwrap_or(false)
    {
        out.insert(0, '_');
    }
    out
}

fn read_plugin_state(plugin_id: &str, state_dir: &Path) -> JsonValue {
    let path = state_dir.join(format!("{plugin_id}.json"));
    match std::fs::read_to_string(path) {
        Ok(text) => {
            serde_json::from_str(&text).unwrap_or(JsonValue::Object(serde_json::Map::new()))
        }
        Err(_) => JsonValue::Object(serde_json::Map::new()),
    }
}

fn value_at_segments<'a>(value: &'a JsonValue, segments: &[String]) -> Option<&'a JsonValue> {
    let mut current = value.get("data").unwrap_or(value);
    for segment in segments {
        current = match current {
            JsonValue::Object(map) => map.get(segment).or_else(|| {
                map.iter()
                    .find(|(key, _)| path_element(key) == *segment)
                    .map(|(_, value)| value)
            })?,
            JsonValue::Array(items) => items
                .iter()
                .find(|item| {
                    ["id", "name", "label", "key", "path", "domain", "host"]
                        .iter()
                        .find_map(|field| item.get(*field).and_then(JsonValue::as_str))
                        .map(path_element)
                        .as_deref()
                        == Some(segment.as_str())
                })
                .or_else(|| segment.parse::<usize>().ok().and_then(|idx| items.get(idx)))?,
            _ => return None,
        };
    }
    Some(current)
}

/// Read-only D-Bus object for a schema-derived child path.
pub struct SchemaChildInterface {
    plugin_id: String,
    path_segments: Vec<String>,
    shm_state_dir: PathBuf,
}

impl SchemaChildInterface {
    fn new(plugin_id: String, path_segments: Vec<String>, shm_state_dir: PathBuf) -> Self {
        Self {
            plugin_id,
            path_segments,
            shm_state_dir,
        }
    }

    fn read_child_state(&self) -> JsonValue {
        let state = read_plugin_state(&self.plugin_id, &self.shm_state_dir);
        value_at_segments(&state, &self.path_segments)
            .cloned()
            .unwrap_or(JsonValue::Object(serde_json::Map::new()))
    }
}

#[zbus::interface(name = "org.opdbus.v1.PluginChildV1")]
impl SchemaChildInterface {
    /// Get a property from this child object's current SHM state.
    async fn get_property(&self, name: String) -> zbus::fdo::Result<String> {
        let state = self.read_child_state();
        let value = state.get(&name).unwrap_or(&JsonValue::Null);
        serde_json::to_string(value).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get all properties for this child object from current SHM state.
    async fn get_all_properties(&self) -> zbus::fdo::Result<String> {
        let state = self.read_child_state();
        serde_json::to_string(&state).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }
}

/// A generic D-Bus interface backed by a plugin schema.
///
/// This struct is registered on the bus for every plugin, making the bridge
/// the authoritative owner of the D-Bus objects defined in the schema.
///
/// Present-state is read directly from SHM
/// (`/dev/shm/opdbus/state/<plugin_id>.json`) on each property access.
/// There is no in-memory cache, no D-Bus `PropertiesChanged` signal watching,
/// and no timer-based polling. If the state file does not exist, an empty
/// properties object (`{}`) is returned, not an error.
pub struct SchemaBackedInterface {
    plugin_id: String,
    route: PluginRoute,
    /// Directory containing per-plugin present-state JSON files.
    shm_state_dir: PathBuf,
    /// The SchemaEngine for real method dispatch (Requirement 5).
    /// `None` when no engine is wired (unit tests that only exercise
    /// method-existence / property-read paths).
    engine: Option<Arc<SchemaEngine>>,
}

impl SchemaBackedInterface {
    /// Creates a new `SchemaBackedInterface` using the default SHM state
    /// directory (`/dev/shm/opdbus/state`) and no engine.
    ///
    /// Prefer [`with_engine`](Self::with_engine) in production so the
    /// interface can dispatch method calls through `SchemaEngine`.
    pub fn new(plugin_id: String, route: PluginRoute) -> Self {
        Self::with_shm_state_dir(plugin_id, route, DEFAULT_SHM_STATE_DIR)
    }

    /// Creates a new `SchemaBackedInterface` wired to a SchemaEngine for
    /// real method dispatch.
    ///
    /// The engine is used by [`call`](Self::call) to dispatch method
    /// invocations through `SchemaEngine::dispatch_method_call`
    /// (Requirement 5 / VAL-DISPATCH-001).
    pub fn with_engine(
        plugin_id: String,
        route: PluginRoute,
        engine: Option<Arc<SchemaEngine>>,
    ) -> Self {
        let mut iface = Self::with_shm_state_dir(plugin_id, route, DEFAULT_SHM_STATE_DIR);
        iface.engine = engine;
        iface
    }

    /// Creates a new `SchemaBackedInterface` with a custom SHM state directory.
    ///
    /// In production, use [`new`](Self::new) which targets `/dev/shm/opdbus/state`.
    /// Tests should supply a temporary directory.
    pub fn with_shm_state_dir(
        plugin_id: String,
        route: PluginRoute,
        shm_state_dir: impl AsRef<Path>,
    ) -> Self {
        Self {
            plugin_id,
            route,
            shm_state_dir: shm_state_dir.as_ref().to_path_buf(),
            engine: None,
        }
    }

    /// Reads the present-state JSON for this plugin from SHM.
    ///
    /// The file is read directly from `<shm_state_dir>/<plugin_id>.json`.
    /// If the file does not exist, an empty JSON object (`{}`) is returned,
    /// not an error. This is a direct file read — no polling, no caching,
    /// no D-Bus signal watching.
    pub fn read_present_state(&self) -> JsonValue {
        let path = self.shm_state_dir.join(format!("{}.json", self.plugin_id));
        match std::fs::read_to_string(&path) {
            Ok(text) => {
                serde_json::from_str(&text).unwrap_or(JsonValue::Object(serde_json::Map::new()))
            }
            Err(_) => JsonValue::Object(serde_json::Map::new()),
        }
    }

    /// The canonical D-Bus object path this interface is registered at
    /// (`/org/opdbus/v1/plugins/<plugin_id>`).
    pub fn dbus_path(&self) -> &str {
        &self.route.dbus_path
    }

    /// The canonical D-Bus interface name for this plugin
    /// (`org.opdbus.v1.Plugin.<PluginName>`).
    pub fn dbus_interface(&self) -> &str {
        &self.route.dbus_interface
    }

    /// Names of every method declared in the plugin's capability surface.
    ///
    /// Every declared `MethodDecl` is exposed as a callable D-Bus method via
    /// [`call`](Self::call).
    pub fn declared_methods(&self) -> Vec<String> {
        self.route.methods.keys().cloned().collect()
    }

    /// Returns `true` if `method` is declared in the plugin's capability
    /// surface (and is therefore callable).
    pub fn exposes_method(&self, method: &str) -> bool {
        self.route.methods.contains_key(method)
    }

    /// Names of every signal declared in the plugin's capability surface.
    ///
    /// Every declared `SignalDecl` is exposed as an emittable D-Bus signal via
    /// [`emit_signal`](Self::emit_signal).
    pub fn declared_signals(&self) -> Vec<String> {
        self.route
            .signals
            .iter()
            .filter_map(|s| s.get("name").and_then(|n| n.as_str()).map(String::from))
            .collect()
    }

    /// Returns `true` if `signal` is declared in the plugin's capability
    /// surface (and is therefore emittable).
    pub fn exposes_signal(&self, signal: &str) -> bool {
        self.route
            .signals
            .iter()
            .any(|s| s.get("name").and_then(|n| n.as_str()) == Some(signal))
    }

    /// Emits a declared D-Bus signal for this plugin on the canonical object
    /// path and interface, carrying `payload_json` as the signal body.
    ///
    /// The signal name is validated against the plugin's capability surface;
    /// emitting a signal that is not declared is rejected. This is the runtime
    /// counterpart to [`declared_signals`](Self::declared_signals): every
    /// `SignalDecl` in the schema is emittable, and nothing else is.
    pub async fn emit_signal(
        &self,
        conn: &Connection,
        signal: &str,
        payload_json: &str,
    ) -> zbus::fdo::Result<()> {
        if !self.exposes_signal(signal) {
            return Err(zbus::fdo::Error::UnknownMethod(format!(
                "signal '{}' is not declared for plugin '{}'",
                signal, self.plugin_id
            )));
        }
        conn.emit_signal(
            Option::<&str>::None,
            self.route.dbus_path.as_str(),
            self.route.dbus_interface.as_str(),
            signal,
            &(payload_json.to_string(),),
        )
        .await
        .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Validates that json_args conforms to the JSON Schema in MethodDecl.args.
    ///
    /// Returns Ok(()) if validation passes, Err(String) with details if it fails.
    /// This validation happens before dispatch, so invalid args cause no mutation
    /// (Requirement 6.3 / VAL-VALIDATE-003).
    fn validate_json_args(&self, method_decl: &JsonValue, json_args: &str) -> Result<(), String> {
        let args_schema = method_decl
            .get("args")
            .ok_or_else(|| "missing args schema".to_string())?;

        // Parse the args schema as a validator
        let validator =
            Validator::new(args_schema).map_err(|e| format!("invalid schema: {}", e))?;

        // Parse the args JSON
        let args_value: JsonValue =
            serde_json::from_str(json_args).map_err(|e| format!("invalid JSON: {}", e))?;

        // Validate against the schema (jsonschema uses draft-07 by default)
        if let Err(e) = validator.validate(&args_value) {
            return Err(format!("validation error: {}", e));
        }

        Ok(())
    }
}

#[zbus::interface(name = "org.opdbus.v1.PluginV1")]
impl SchemaBackedInterface {
    /// Generic method call dispatcher.
    ///
    /// All schema-defined methods are funneled through this call, allowing
    /// dynamic dispatch without compile-time traits for every plugin.
    ///
    /// Dispatch pipeline (Requirement 7):
    ///   1. Method lookup → reject if not declared (UnknownMethod)
    ///   2. Arg validation → reject if invalid (InvalidArgs)
    ///   3. Capability check → reject if required_capability not granted (AccessDenied)
    ///   4. SchemaEngine.mutate → record in event chain (Requirement 5)
    async fn call(&self, method: String, json_args: String) -> zbus::fdo::Result<String> {
        // 1. Method-existence gate: reject undeclared methods (Requirement 6).
        // If the methods map is empty, ALL invocations are rejected as UnknownMethod.
        let method_decl = match self.route.methods.get(&method) {
            Some(decl) => decl,
            None => return Err(zbus::fdo::Error::UnknownMethod(method)),
        };

        info!(plugin_id = %self.plugin_id, method, "D-Bus method call received");

        // 2. Argument validation against MethodDecl.args JSON Schema (Requirement 6.3).
        // json_args must conform to the schema; rejection as InvalidArgs without calling mutate.
        if let Err(e) = self.validate_json_args(method_decl, &json_args) {
            return Err(zbus::fdo::Error::InvalidArgs(format!(
                "arguments do not conform to schema for method '{}': {}",
                method, e
            )));
        }

        // 3. Capability enforcement (Requirement 7.2, VAL-ENFORCE-002/003).
        // For D-Bus calls, capability checks are delegated to the bridge.
        // The caller identity (footprint) must grant the required_capability if non-null.
        // This enforcement happens at bridge layer only (VAL-ENFORCE-006).
        let required_cap = method_decl
            .get("required_capability")
            .and_then(|c| c.as_str())
            .filter(|s| !s.is_empty());

        if let Some(cap) = required_cap {
            // For D-Bus, we check the current sled's footprint grants.
            // This is the primary gate: footprint validation already passed via
            // the sled's temporal hash check (NFR-006).
            let grants = match op_identity::read_sled() {
                Ok((ptr, _mmap)) => {
                    let sled = unsafe { &*ptr };
                    load_capability_grants(&hex::encode(sled.hashed_footprint))
                }
                Err(_) => std::collections::HashSet::new(),
            };

            if !grants.contains(cap) {
                // VAL-ENFORCE-003: Missing capability denied without calling mutate.
                return Err(zbus::fdo::Error::AccessDenied(format!(
                    "capability '{}' required for method '{}' is not granted",
                    cap, method
                )));
            }
        }

        // 4. Real dispatch through SchemaEngine (Requirement 5).
        //    json_args is passed verbatim — no default, no placeholder
        //    (Requirement 5.4 / VAL-DISPATCH-004).
        let engine = self.engine.as_ref().ok_or_else(|| {
            zbus::fdo::Error::Failed(
                "SchemaEngine not wired to this interface — dispatch unavailable".to_string(),
            )
        })?;

        // The capability_id is read from the MethodDecl's required_capability
        // (enforcement already performed above, here it's threaded into event chain).
        let capability_id = required_cap.map(|s| s.to_string());

        // The actor_id for a D-Bus dispatch is the caller's bus identity.
        // The interceptor-extracted footprint/session is the primary gate;
        // here we use the plugin's bus name as the actor for audit purposes.
        let actor_id = format!("dbus:{}", self.plugin_id);

        let result = engine
            .dispatch_method_call(
                &self.plugin_id,
                &method,
                &json_args,
                capability_id.as_deref(),
                &actor_id,
            )
            .await
            .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))?;

        // 5. Return the serialized result to the D-Bus caller.
        serde_json::to_string(&result).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get a property value from SHM present-state.
    ///
    /// Reads `/dev/shm/opdbus/state/<plugin_id>.json` on each call.
    /// If the state file does not exist, returns an empty value for the
    /// requested property (not an error).
    async fn get_property(&self, name: String) -> zbus::fdo::Result<String> {
        let state = self.read_present_state();
        let val = state.get(&name).unwrap_or(&JsonValue::Null);
        serde_json::to_string(val).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get all present-state properties as a JSON object.
    ///
    /// Reads `/dev/shm/opdbus/state/<plugin_id>.json` on each call.
    /// If the state file does not exist, returns `{}`.
    async fn get_all_properties(&self) -> zbus::fdo::Result<String> {
        let state = self.read_present_state();
        serde_json::to_string(&state).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Set a property value.
    ///
    /// Present-state is managed by the producer (`op-projection`) via SHM.
    /// The bridge is a reader, not a writer, of present-state. This method
    /// returns an error indicating that property writes must go through the
    /// producer's mutation pipeline.
    async fn set_property(&self, _name: String, _json_value: String) -> zbus::fdo::Result<()> {
        Err(zbus::fdo::Error::Failed(
            "Present-state is managed by op-projection via SHM; \
             use the mutation pipeline to change properties"
                .to_string(),
        ))
    }
}

#[derive(Debug, thiserror::Error)]
pub enum SchemaRouterError {
    #[error("Plugin not found: {0}")]
    PluginNotFound(String),
    #[error("Method {method} not found for plugin {plugin_id}. Available: {available:?}")]
    MethodNotFound {
        plugin_id: String,
        method: String,
        available: Vec<String>,
    },
    #[error("Property {property} not found for plugin {plugin_id}. Available: {available:?}")]
    PropertyNotFound {
        plugin_id: String,
        property: String,
        available: Vec<String>,
    },
    #[error("D-Bus unavailable")]
    DbusUnavailable,
    #[error("D-Bus proxy build failed: {0}")]
    ProxyBuildFailed(String),
    #[error("D-Bus call failed: {method}: {error}")]
    DbusCallFailed { method: String, error: String },
    #[error("Serialization failed: {0}")]
    SerializationFailed(String),
}

impl From<SchemaRouterError> for tonic::Status {
    fn from(err: SchemaRouterError) -> Self {
        match err {
            SchemaRouterError::PluginNotFound(id) => {
                tonic::Status::not_found(format!("Plugin not found: {}", id))
            }
            SchemaRouterError::MethodNotFound {
                plugin_id,
                method,
                available,
            } => tonic::Status::not_found(format!(
                "Method {} not found for plugin {}. Available: {:?}",
                method, plugin_id, available
            )),
            SchemaRouterError::PropertyNotFound {
                plugin_id,
                property,
                available,
            } => tonic::Status::not_found(format!(
                "Property {} not found for plugin {}. Available: {:?}",
                property, plugin_id, available
            )),
            SchemaRouterError::DbusUnavailable => {
                tonic::Status::unavailable("D-Bus connection unavailable")
            }
            SchemaRouterError::ProxyBuildFailed(msg) => {
                tonic::Status::internal(format!("D-Bus proxy build failed: {}", msg))
            }
            SchemaRouterError::DbusCallFailed { method, error } => {
                tonic::Status::internal(format!("D-Bus call failed: {}: {}", method, error))
            }
            SchemaRouterError::SerializationFailed(msg) => {
                tonic::Status::internal(format!("Serialization failed: {}", msg))
            }
        }
    }
}

fn json_to_zvariant_value(
    value: &serde_json::Value,
) -> Result<zbus::zvariant::Value<'static>, SchemaRouterError> {
    use zbus::zvariant::Value as ZValue;
    match value {
        serde_json::Value::Null => Ok(ZValue::from("")),
        serde_json::Value::Bool(b) => Ok(ZValue::from(*b)),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(ZValue::from(i))
            } else if let Some(f) = n.as_f64() {
                Ok(ZValue::from(f))
            } else {
                Ok(ZValue::from(n.to_string()))
            }
        }
        serde_json::Value::String(s) => Ok(ZValue::from(s.clone())),
        serde_json::Value::Array(arr) => {
            let items: Vec<String> = arr
                .iter()
                .map(|v| match v {
                    serde_json::Value::String(s) => s.clone(),
                    other => other.to_string(),
                })
                .collect();
            Ok(ZValue::from(items))
        }
        serde_json::Value::Object(_) => {
            let s = serde_json::to_string(value)
                .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))?;
            Ok(ZValue::from(s))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use std::fs;
    use std::path::PathBuf;

    /// Builds a test `PluginRoute` with a single method and two properties.
    fn test_route() -> PluginRoute {
        let mut methods = HashMap::new();
        methods.insert(
            "GetStatus".to_string(),
            json!({ "type": "object", "properties": {} }),
        );
        let mut properties = HashMap::new();
        properties.insert("status".to_string(), json!({ "type": "string" }));
        properties.insert("uptime".to_string(), json!({ "type": "integer" }));
        let signals = vec![json!({
            "name": "StatusChanged",
            "payload": { "type": "object" },
            "subid": "evt.service.test.status-changed@v1"
        })];
        PluginRoute {
            plugin_id: "test_plugin".to_string(),
            dbus_path: "/org/opdbus/v1/plugins/test_plugin".to_string(),
            dbus_destination: "org.opdbus.v1".to_string(),
            dbus_interface: "org.opdbus.v1.Plugin.TestPlugin".to_string(),
            methods,
            signals,
            properties,
        }
    }

    /// Creates a unique temp directory under `/dev/shm` for SHM state files.
    fn test_state_dir() -> PathBuf {
        let id = std::process::id();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = PathBuf::from(format!("/dev/shm/opdbus-test-state-{}-{}", id, nanos));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).expect("create test state dir");
        dir
    }

    fn cleanup(dir: &Path) {
        let _ = fs::remove_dir_all(dir);
    }

    // ── R9.5 / VAL-PROD-007: Missing state file returns empty object ──

    #[test]
    fn should_return_empty_object_when_state_file_missing() {
        let state_dir = test_state_dir();
        let route = test_route();
        let iface =
            SchemaBackedInterface::with_shm_state_dir("test_plugin".to_string(), route, &state_dir);

        // read_present_state returns empty object when file is missing
        let state = iface.read_present_state();
        assert_eq!(
            state,
            json!({}),
            "missing state file must return empty object, not error"
        );

        // Verify it's a JSON object (not null, not error)
        assert!(
            state.is_object(),
            "missing state file must return a JSON object"
        );
        assert!(
            state.as_object().unwrap().is_empty(),
            "missing state file must return an empty JSON object"
        );

        cleanup(&state_dir);
    }

    // ── R9.2 / VAL-PROD-007: Present-state read from SHM, not D-Bus ─────

    #[test]
    fn should_read_present_state_from_shm() {
        let state_dir = test_state_dir();
        let route = test_route();

        // Write a present-state file to SHM
        let state_path = state_dir.join("test_plugin.json");
        let state_json = json!({
            "status": "active",
            "uptime": 42,
            "extra_field": "not_in_schema"
        });
        fs::write(&state_path, serde_json::to_vec_pretty(&state_json).unwrap())
            .expect("write state file");

        let iface =
            SchemaBackedInterface::with_shm_state_dir("test_plugin".to_string(), route, &state_dir);

        // read_present_state returns the full state from SHM
        let state = iface.read_present_state();
        assert_eq!(
            state["status"],
            json!("active"),
            "present-state must be read from SHM file"
        );
        assert_eq!(
            state["uptime"],
            json!(42),
            "present-state must be read from SHM file"
        );
        assert_eq!(
            state["extra_field"],
            json!("not_in_schema"),
            "present-state includes all fields from SHM, even those not in schema"
        );

        // Verify the data came from the file, not from schema defaults
        assert_ne!(
            state["status"],
            JsonValue::Null,
            "status must come from SHM file, not default"
        );

        cleanup(&state_dir);
    }

    // ── R9.2: get_property reads from SHM ───────────────────────────────

    #[tokio::test]
    async fn should_get_property_from_shm() {
        let state_dir = test_state_dir();
        let route = test_route();

        let state_json = json!({ "status": "running", "uptime": 100 });
        let state_path = state_dir.join("test_plugin.json");
        fs::write(&state_path, serde_json::to_vec_pretty(&state_json).unwrap())
            .expect("write state file");

        let iface =
            SchemaBackedInterface::with_shm_state_dir("test_plugin".to_string(), route, &state_dir);

        let result = iface.get_property("status".to_string()).await;
        assert!(
            result.is_ok(),
            "get_property should succeed when state file exists"
        );
        let val: serde_json::Value = serde_json::from_str(&result.unwrap()).expect("parse result");
        assert_eq!(val, json!("running"));

        cleanup(&state_dir);
    }

    // ── R9.5: get_property on missing file returns null, not error ──────

    #[tokio::test]
    async fn should_get_property_return_null_when_state_file_missing() {
        let state_dir = test_state_dir();
        let route = test_route();

        let iface =
            SchemaBackedInterface::with_shm_state_dir("test_plugin".to_string(), route, &state_dir);

        let result = iface.get_property("status".to_string()).await;
        assert!(
            result.is_ok(),
            "get_property must not error when state file is missing"
        );
        let val: serde_json::Value = serde_json::from_str(&result.unwrap()).expect("parse result");
        assert_eq!(val, JsonValue::Null);

        cleanup(&state_dir);
    }

