//! Build-time plugin proto generator
//!
//! This module generates typed gRPC service definitions from PluginSchema.method
//! declarations. Each plugin's methods become individually typed RPCs with
//! request/response messages derived from the JSON Schema in MethodDecl.args/returns.
//!
//! Generated services integrate with tonic-reflection so clients can discover
//! typed endpoints per plugin, while the implementation still dispatches through
//! SchemaEngine.mutate for enforcement.

use op_state_store::{FieldType, MethodDecl, PluginSchema, SideEffect};
use std::collections::HashMap;
use std::fmt::Write;

/// Generate typed proto service for a plugin schema
pub fn generate_plugin_proto(plugin_name: &str, schema: &PluginSchema) -> String {
    let mut output = String::new();

    // Package per plugin
    let package = format!("plugin.{}.v1", plugin_name);
    writeln!(output, "syntax = \"proto3\";").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "package {};", package).unwrap();
    writeln!(output).unwrap();

    writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
    writeln!(output).unwrap();

    // Service for this plugin
    let service_name = to_pascal_case(plugin_name);
    writeln!(output, "service {}Plugin {{", service_name).unwrap();

    // Generate RPC for each method
    let mut method_names: Vec<&String> = schema.methods.keys().collect();
    method_names.sort();

    for method_name in method_names {
        let method = &schema.methods[method_name];
        let request_type = format!("{}Request", to_pascal_case(method_name));
        let response_type = format!("{}Response", to_pascal_case(method_name));

        writeln!(
            output,
            "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
            method_name
        )
        .unwrap();
    }

    writeln!(output, "}}").unwrap();
    output
}

/// Generate full proto with all plugin services for a catalog
pub fn generate_catalog_proto(schemas: &HashMap<String, PluginSchema>) -> String {
    let mut output = String::new();

    // Header
    writeln!(output, "syntax = \"proto3\";").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "package plugin.v1;").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
    writeln!(output).unwrap();

    // Generate service for each plugin
    let mut plugin_names: Vec<&String> = schemas.keys().collect();
    plugin_names.sort();

    for plugin_name in plugin_names {
        let schema = &schemas[plugin_name];
        let service_name = to_pascal_case(plugin_name);

        writeln!(output, "// Plugin: {}", plugin_name).unwrap();
        writeln!(output, "service {} {{", service_name).unwrap();

        let mut method_names: Vec<&String> = schema.methods.keys().collect();
        method_names.sort();

        for method_name in method_names {
            writeln!(
                output,
                "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
                method_name
            )
            .unwrap();
        }

        writeln!(output, "}}").unwrap();
        writeln!(output).unwrap();
    }

    output
}

fn to_pascal_case(s: &str) -> String {
    s.split(['_', '-', ' '])
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(chars).collect(),
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use simd_json::json;

    #[test]
    fn test_generate_plugin_proto() {
        let schema = test_rovs_commands_schema();
        let proto = generate_plugin_proto("rovs_commands", &schema);

        assert!(proto.contains("package plugin.rovs.commands.v1"));
        assert!(proto.contains("service RovsCommands {"));
        assert!(proto.contains("rpc create_bridge(google.protobuf.Struct)"));
        assert!(proto.contains("rpc list_bridges(google.protobuf.Struct)"));
    }

    #[test]
    fn test_generate_catalog_proto() {
        let mut schemas = HashMap::new();
        schemas.insert("rovs_commands".to_string(), test_rovs_commands_schema());
        schemas.insert("wireguard".to_string(), test_wireguard_schema());

        let proto = generate_catalog_proto(&schemas);

        assert!(proto.contains("service RovsCommands {"));
        assert!(proto.contains("service Wireguard {"));
    }

    fn test_rovs_commands_schema() -> PluginSchema {
        let create_bridge_method = MethodDecl {
            name: "create_bridge".to_string(),
            args: json!({
                "type": "object",
                "required": ["bridge_name"],
                "properties": {
                    "bridge_name": {"type": "string"}
                }
            }),
            returns: Some(json!({"type": "object"})),
            side_effect: SideEffect::Mutation,
            idempotent: false,
            required_capability: Some("cap.network.ovsdb.bridge.create@v1".to_string()),
            subid: "mut.network.ovsdb.bridge.create@v1".to_string(),
        };

        let list_bridges_method = MethodDecl {
            name: "list_bridges".to_string(),
            args: json!({"type": "object"}),
            returns: Some(json!({"type": "array", "items": {"type": "string"}})),
            side_effect: SideEffect::Read,
            idempotent: true,
            required_capability: Some("cap.network.ovsdb.bridge.list@v1".to_string()),
            subid: "obs.network.ovsdb.bridge.list@v1".to_string(),
        };

        let mut methods = HashMap::new();
        methods.insert("create_bridge".to_string(), create_bridge_method);
        methods.insert("list_bridges".to_string(), list_bridges_method);

        PluginSchema::builder("rovs_commands")
            .version("1.0.0")
            .description("OVSDB command execution methods")
            .methods(methods)
            .build()
    }

    fn test_wireguard_schema() -> PluginSchema {
        let get_status_method = MethodDecl {
            name: "GetStatus".to_string(),
            args: json!({"type": "object", "properties": {}}),
            returns: Some(json!({
                "type": "object",
                "properties": {
                    "connected": {"type": "boolean"}
                }
            })),
            side_effect: SideEffect::Read,
            idempotent: true,
            required_capability: None,
            subid: "obs.network.wireguard.get_status@v1".to_string(),
        };

        let mut methods = HashMap::new();
        methods.insert("GetStatus".to_string(), get_status_method);

        PluginSchema::builder("wireguard")
            .version("1.0.0")
            .description("WireGuard interface management")
            .methods(methods)
            .build()
    }
}

//! Generate plugin-specific gRPC service definitions from PluginSchema
//!
//! Reads plugin schema information and generates typed proto files that integrate
//! with the main operation.proto file descriptor set. Each method declared in a
//! plugin's schema gets its own typed RPC instead of going through generic CallMethod.

use std::collections::HashMap;
use std::fs;
use std::path::Path;

/// Generate typed proto for plugin methods
fn generate_plugin_proto(plugin_id: &str, methods: &HashMap<String, serde_json::Value>) -> String {
    let mut output = String::new();
    let service_name = to_pascal_case(plugin_id);

    writeln!(output, "// Auto-generated from PluginSchema.methods").unwrap();
    writeln!(output, "// Plugin: {}", plugin_id).unwrap();
    writeln!(output).unwrap();

    writeln!(output, "service {} {{", service_name).unwrap();

    let mut method_names: Vec<&String> = methods.keys().collect();
    method_names.sort();

    for method_name in method_names {
        let method = &methods[method_name];
        let required_cap = method
            .get("required_capability")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        writeln!(
            output,
            "  // subid: {}",
            method.get("subid").and_then(|v| v.as_str()).unwrap_or("")
        )
        .unwrap();
        writeln!(
            output,
            "  // capability: {}",
            if required_cap.is_empty() { "none" } else { required_cap }
        )
        .unwrap();
        writeln!(
            output,
            "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
            method_name
        )
        .unwrap();
    }

    writeln!(output, "}}").unwrap();
    output
}

fn to_pascal_case(s: &str) -> String {
    s.split(['_', '-', '.'])
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(chars).collect(),
            }
        })
        .collect()
}

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        anyhow::bail!("Usage: generate-plugin-protos <output_dir> <schema_json>");
    }

    let output_dir = &args[1];
    let schema_json = &args[2];

    let schema: serde_json::Value = serde_json::from_str(schema_json)?;
    let methods = schema
        .get("methods")
        .and_then(|m| m.as_object())
        .unwrap_or(&serde_json::Map::new())
        .clone();

    let plugin_id = schema
        .get("name")
        .and_then(|n| n.as_str())
        .unwrap_or("unknown");

    let plugin_proto = generate_plugin_proto(plugin_id, &methods);

    let output_path = Path::new(output_dir).join(format!("{}.proto", plugin_id));
    fs::write(&output_path, plugin_proto)?;

    println!("cargo:rerun-if-changed=generate-plugin-protos");
    Ok(())
}

