//! Build-time plugin proto generator
//!
//! Generates typed gRPC service definitions from PluginSchema.method declarations.
//! Each plugin's methods become individually typed RPCs with request/response
//! messages derived from the JSON Schema in MethodDecl.args/returns.
//!
//! This file is included in build.rs to generate plugin-specific protos at build time.

use std::collections::HashMap;
use std::fmt::Write;

/// Generate proto service for a plugin based on its method declarations
pub fn generate_plugin_service(plugin_id: &str, methods: &HashMap<String, serde_json::Value>) -> String {
    let mut output = String::new();
    let service_name = to_pascal_case(plugin_id);

    writeln!(output, "// Auto-generated from PluginSchema.methods for {}", plugin_name).unwrap();
    writeln!(output, "// Plugin ID: {}", plugin_id).unwrap();
    writeln!(output).unwrap();

    writeln!(output, "service {} {{", service_name).unwrap();

    let mut method_names: Vec<&String> = methods.keys().collect();
    method_names.sort();

    for method_name in method_names {
        let method = &methods[method_name];
        let subid = method.get("subid").and_then(|v| v.as_str()).unwrap_or("");
        let cap = method.get("required_capability").and_then(|v| v.as_str()).unwrap_or("");

        writeln!(
            output,
            "  // subid: {} capability: {}",
            subid,
            if cap.is_empty() { "none" } else { cap }
        ).unwrap();
        writeln!(
            output,
            "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
            method_name
        ).unwrap();
    }

    writeln!(output, "}}").unwrap();
    output
}

/// Generate full proto with all plugin services
pub fn generate_plugins_proto(all_schemas: &Vec<(String, serde_json::Value)>) -> String {
    let mut output = String::new();

    writeln!(output, "syntax = \"proto3\";").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "package plugin.v1;").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
    writeln!(output).unwrap();

    let mut plugin_ids: Vec<String> = all_schemas.iter().map(|(id, _)| id.clone()).collect();
    plugin_ids.sort();

    for plugin_id in plugin_ids {
        let (_, schema) = all_schemas.iter().find(|(id, _)| *id == plugin_id).unwrap();
        let methods = schema
            .get("methods")
            .and_then(|m| m.as_object())
            .unwrap_or(&serde_json::Map::new())
            .clone();

        writeln!(output, "// ================================================").unwrap();
        writeln!(output, "// Plugin: {}", plugin_id).unwrap();
        writeln!(output, "// ================================================").unwrap();
        writeln!(output).unwrap();

        let service_name = to_pascal_case(plugin_id);
        writeln!(output, "service {} {{", service_name).unwrap();

        let mut method_names: Vec<&String> = methods.keys().collect();
        method_names.sort();

        for method_name in method_names {
            let method = &methods[method_name];
            let subid = method.get("subid").and_then(|v| v.as_str()).unwrap_or("");
            writeln!(
                output,
                "  // subid: {}",
                subid
            ).unwrap();
            writeln!(
                output,
                "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
                method_name
            ).unwrap();
        }

        writeln!(output, "}}").unwrap();
        writeln!(output).unwrap();
    }

    output
}

fn to_pascal_case(s: &str) -> String {
    s.split(['_', '-', '.'])
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(chars).collect(),
            }
        })
        .collect()
}

