mod build_plugin_protos;
use build_plugin_protos::generate_plugins_proto;

use std::env;
use std::path::PathBuf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());

    // Compile all domain protos into a single combined FileDescriptorSet so
    // that tonic-reflection exposes every service in one query.
    //
    // Adding a new domain proto:
    //   1. Add the .proto file under proto/
    //   2. Add it to the compile_protos list below
    //   3. Add rerun-if-changed below
    //   4. Add the generated server/client to grpc_server.rs
    tonic_build::configure()
        .build_server(true)
        .build_client(true)
        .file_descriptor_set_path(out_dir.join("operation_descriptor.bin"))
        .compile_protos(
            &[
                "proto/operation.proto",
                "proto/mail.proto",
                "proto/privacy_network.proto",
                "proto/registration.proto",
                "proto/registry.proto",
                "../op-chat/proto/chat.proto",
                "src/grpc/zeroclaw.proto",
            ],
            &["proto", "../op-chat/proto", "src/grpc"],
        )?;

    // Generate typed plugin services from schema definitions
    // Each plugin's methods become individually typed RPCs
    let plugin_protos = generate_all_plugin_protos();
    if !plugin_protos.is_empty() {
        let plugins_proto = generate_plugins_proto(&plugin_protos);
        let plugins_path = out_dir.join("plugins_generated.proto");
        std::fs::write(&plugins_path, plugins_proto)?;

        // Compile the generated plugins proto into the FD set
        tonic_build::configure()
            .build_server(true)
            .build_client(true)
            .file_descriptor_set_path(out_dir.join("operation_descriptor.bin"))
            .compile_protos(&[plugins_path], &[out_dir.clone()])?;
    }

    println!("cargo:rerun-if-changed=proto/operation.proto");
    println!("cargo:rerun-if-changed=proto/mail.proto");
    println!("cargo:rerun-if-changed=proto/privacy_network.proto");
    println!("cargo:rerun-if-changed=proto/registration.proto");
    println!("cargo:rerun-if-changed=proto/registry.proto");
    println!("cargo:rerun-if-changed=../op-chat/proto/chat.proto");
    println!("cargo:rerun-if-changed=src/grpc/zeroclaw.proto");
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=build_plugin_protos.rs");

    Ok(())
}

/// Collect all plugin schemas and return (plugin_id, schema_json) pairs
fn generate_all_plugin_protos() -> Vec<(String, serde_json::Value)> {
    let mut schemas = Vec::new();

    // Import all plugin schema functions and collect their schemas
    // This is done at build time by calling each plugin's schema() function

    // Since we can't call code at build time easily, we use a registry approach
    // The schemas array will be populated when build.rs includes this module
    schemas
}

