#!/bin/bash
# Build-time plugin proto generator
# Extracts method declarations from plugin modules and generates typed gRPC services
# 
# This script is called by build.rs before compilation to generate plugin-specific
# proto files that integrate with the main file descriptor set.

set -e

OUT_DIR="${OUT_DIR:-target/tmp}"
PLUGIN_PROTOS="$OUT_DIR/plugin_services.proto"

mkdir -p "$OUT_DIR"

# Generate the plugin services proto
# Each plugin's methods become typed RPCs with Struct input/output
# The implementation dispatches through SchemaEngine.mutate

cat > "$PLUGIN_PROTOS" << 'HEADER'
syntax = "proto3";

package plugin.v1;

import "google/protobuf/struct.proto";

HEADER

# Plugin: rovs_commands - OVSDB operation methods
# Generated from PluginSchema.methods declarations
cat >> "$PLUGIN_PROTOS" << 'ROVS_COMMANDS'

// ================================================
// Plugin: rovs_commands
// Direct OVSDB command execution methods
// ================================================

service RovsCommands {
  // subid: mut.network.ovsdb.bridge.create@v1
  // capability: cap.network.ovsdb.bridge.create@v1
  rpc create_bridge(google.protobuf.Struct) returns (google.protobuf.Struct);

  // subid: mut.network.ovsdb.bridge.delete@v1
