//! RovsCommands typed gRPC service
//!
//! Generates typed gRPC RPCs from PluginSchema.method declarations for the
//! rovs_commands plugin. All calls dispatch through SchemaEngine.mutate to ensure
//! capability enforcement and event chain recording.

use crate::interceptor::{GhostbridgeIdentity, GhostbridgeInterceptor};
use crate::mutation_engine::MutationEngine;
use crate::proto::rovs_commands::rovs_commands_server::RovsCommandsServer;
use crate::proto::rovs_commands::{
    CreateBridgeRequest, CreateBridgeResponse, DeleteBridgeRequest, DeleteBridgeResponse,
    AddPortRequest, AddPortResponse, RemovePortRequest, RemovePortResponse,
    ListBridgesRequest, ListBridgesResponse, ListPortsRequest, ListPortsResponse,
    ListDbsRequest, ListDbsResponse,
};
use prost_types::Struct as ProstStruct;
use serde_json::Value as JsonValue;
use simd_json::OwnedValue;
use std::sync::Arc;
use tonic::{Request, Response, Status};
use tracing::{info, warn};

/// Typed gRPC service implementation for rovs_commands plugin
#[derive(Clone)]
pub struct RovsCommandsService {
    mutation_engine: Arc<MutationEngine>,
}

impl RovsCommandsService {
    pub fn new(mutation_engine: Arc<MutationEngine>) -> Self {
        Self { mutation_engine }
    }

    /// Convert Prost Struct to simd_json for SchemaEngine dispatch
    fn prost_to_simd(&self, struct_val: &ProstStruct) -> OwnedValue {
        let mut map = simd_json::value::owned::Object::new();
        for (k, v) in &struct_val.fields {
            map.insert(k.clone(), prost_value_to_simd(v));
        }
        OwnedValue::Object(Box::new(map))
    }

    /// Convert simd_json result to Prost Struct
    fn simd_to_prost(&self, value: &OwnedValue) -> ProstStruct {
        match value.as_object() {
            Some(obj) => {
                let fields = obj
                    .iter()
                    .map(|(k, v)| (k.to_string(), simd_to_prost_value(v)))
                    .collect();
                ProstStruct { fields }
            }
            None => ProstStruct::default(),
        }
    }

    /// Dispatch a method call through SchemaEngine for capability enforcement
    async fn dispatch_method(
        &self,
        method: &str,
        args: OwnedValue,
        actor_id: &str,
    ) -> Result<OwnedValue, Status> {
        let result = self
            .mutation_engine
            .mutate(
                "rovs_commands",
                format!("/org/opdbus/v1/plugins/rovs_commands"),
                crate::mutation_engine::ChangeType::MethodCall,
                Some(method.to_string()),
                args,
                actor_id.to_string(),
                None,
            )
            .await
            .map_err(|e| Status::internal(format!("dispatch failed: {}", e)))?;

        Ok(result)
    }
}

#[tonic::async_trait]
impl RovsCommandsServer for RovsCommandsService {
    async fn create_bridge(
        &self,
        request: Request<CreateBridgeRequest>,
    ) -> Result<Response<CreateBridgeResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = self.prost_to_simd(&request.into_inner().bridge_name)?;
        let result = self.dispatch_method("create_bridge", args, &actor_id).await?;

        Ok(Response::new(CreateBridgeResponse {
            result: Some(self.simd_to_prost(&result)),
        }))
    }

    async fn delete_bridge(
        &self,
        request: Request<DeleteBridgeRequest>,
    ) -> Result<Response<DeleteBridgeResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = self.prost_to_simd(&request.into_inner().bridge_name)?;
        let result = self.dispatch_method("delete_bridge", args, &actor_id).await?;

        Ok(Response::new(DeleteBridgeResponse {
            result: Some(self.simd_to_prost(&result)),
        }))
    }

    async fn add_port(
        &self,
        request: Request<AddPortRequest>,
    ) -> Result<Response<AddPortResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = self.prost_to_simd(&request.into_inner().port_config)?;
        let result = self.dispatch_method("add_port", args, &actor_id).await?;

        Ok(Response::new(AddPortResponse {
            result: Some(self.simd_to_prost(&result)),
        }))
    }

    async fn remove_port(
        &self,
        request: Request<RemovePortRequest>,
    ) -> Result<Response<RemovePortResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = self.prost_to_simd(&request.into_inner().port_name)?;
        let result = self.dispatch_method("remove_port", args, &actor_id).await?;

        Ok(Response::new(RemovePortResponse {
            result: Some(self.simd_to_prost(&result)),
        }))
    }

    async fn list_bridges(
        &self,
        request: Request<ListBridgesRequest>,
    ) -> Result<Response<ListBridgesResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = simd_json::json!({});
        let result = self.dispatch_method("list_bridges", args, &actor_id).await?;

        Ok(Response::new(ListBridgesResponse {
            bridges_json: simd_json::to_string(&result).unwrap_or_default(),
        }))
    }

    async fn list_ports(
        &self,
        request: Request<ListPortsRequest>,
    ) -> Result<Response<ListPortsResponse>, Status> {
        let identity = request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = simd_json::json!({});
        let result = self.dispatch_method("list_ports", args, &actor_id).await?;

        Ok(Response::new(ListPortsResponse {
            ports_json: simd_json::to_string(&result).unwrap_or_default(),
        }))
    }

    async fn list_dbs(
        &self,
        _request: Request<ListDbsRequest>,
    ) -> Result<Response<ListDbsResponse>, Status> {
        let identity = _request.extensions().get::<GhostbridgeIdentity>().cloned();
        let actor_id = format!(
            "grpc:{}",
            identity
                .as_ref()
                .map(|i| i.footprint.as_str())
                .unwrap_or("anonymous")
        );

        let args = simd_json::json!({});
        let result = self.dispatch_method("list_dbs", args, &actor_id).await?;

        Ok(Response::new(ListDbsResponse {
            databases_json: simd_json::to_string(&result).unwrap_or_default(),
        }))
    }
}

// Helper functions
fn prost_value_to_simd(value: &prost_types::Value) -> OwnedValue {
    use prost_types::value::Kind;
    match &value.kind {
        None | Some(Kind::NullValue(_)) => simd_json::json!(null),
        Some(Kind::BoolValue(b)) => simd_json::json!(*b),
        Some(Kind::NumberValue(n)) => simd_json::json!(*n),
        Some(Kind::StringValue(s)) => simd_json::json!(s),
        Some(Kind::StructValue(s)) => {
            let mut map = simd_json::value::owned::Object::new();
            for (k, v) in &s.fields {
                map.insert(k.clone(), prost_value_to_simd(v));
            }
            simd_json::OwnedValue::Object(Box::new(map))
        }
        Some(Kind::ListValue(l)) => {
            simd_json::OwnedValue::from(
                l.values.iter().map(prost_value_to_simd).collect::<Vec<_>>(),
            )
        }
    }
}

fn simd_to_prost_value(value: &OwnedValue) -> prost_types::Value {
    use prost_types::value::Kind;
    match value {
        simd_json::OwnedValue::Null => prost_types::Value {
            kind: Some(Kind::NullValue(0)),
        },
        simd_json::OwnedValue::Bool(b) => prost_types::Value {
            kind: Some(Kind::BoolValue(*b)),
        },
        simd_json::OwnedValue::Float(f) => prost_types::Value {
            kind: Some(Kind::NumberValue(*f)),
        },
        simd_json::OwnedValue::String(s) => prost_types::Value {
            kind: Some(Kind::StringValue(s.to_string())),
        },
        simd_json::OwnedValue::Array(arr) => prost_types::Value {
            kind: Some(Kind::ListValue(prost_types::ListValue {
                values: arr.iter().map(simd_to_prost_value).collect(),
            })),
        },
        simd_json::OwnedValue::Object(obj) => prost_types::Value {
            kind: Some(Kind::StructValue(prost_types::Struct {
                fields: obj
                    .iter()
                    .map(|(k, v)| (k.to_string(), simd_to_prost_value(v)))
                    .collect(),
            })),
        },
        _ => prost_types::Value {
            kind: Some(Kind::NullValue(0)),
        },
    }
}

