fn method_decl_from_schemars<Input: JsonSchema>(
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    required_capability: &str,
    subid: &str,
) -> MethodDecl {
    MethodDecl {
        name: name.to_string(),
        args: serde_json::to_value(schemars::schema_for!(Input)).unwrap(),
        returns: Some(json!({"type": "object"})),
        side_effect,
        idempotent,
        required_capability: Some(required_capability.to_string()),
        subid: subid.to_string(),
    }
}

