pub(crate) use super::xray::xray_schema as xray_plugin_schema;
pub(crate) use super::zeroclaw::zeroclaw_schema as zeroclaw_plugin_schema;

// ── Shared utility functions (not schemas) ─────────────────────────────────────

use op_state_store::{FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
use simd_json::{json, OwnedValue as Value};

/// Materialize a deterministic initial live state from a plugin schema.
///
/// This is the schema-side bootstrap for D-Bus projection creation. It never
/// queries a plugin backend and never invents data outside the contract:
/// field defaults win, then examples, then an empty value matching the field
/// type. The MutationEngine writes this once when no projection exists yet;
/// later mutations replace it through the normal `/dev/shm/opdbus/projections`
/// write door.
pub(crate) fn materialize_state_from_schema(schema: &PluginSchema) -> Value {
    if let Some(example) = &schema.example {
        return example.clone();
    }

    let mut state = simd_json::value::owned::Object::new();
    let mut fields = schema.fields.iter().collect::<Vec<_>>();
    fields.sort_by(|(a, _), (b, _)| a.cmp(b));

    for (name, field) in fields {
        state.insert(name.clone(), materialize_field(field));
    }

    Value::Object(Box::new(state))
}

fn materialize_field(field: &FieldSchema) -> Value {
    if let Some(value) = &field.default {
        return value.clone();
    }
    if let Some(value) = &field.example {
        return value.clone();
    }

    materialize_field_type(&field.field_type)
}

fn materialize_field_type(field_type: &FieldType) -> Value {
    match field_type {
        FieldType::String => json!(""),
        FieldType::Integer => json!(0),
        FieldType::Float => json!(0.0),
        FieldType::Boolean => json!(false),
        FieldType::Array(_) => json!([]),
        FieldType::Object(fields) => {
            let mut object = simd_json::value::owned::Object::new();
            let mut fields = fields.iter().collect::<Vec<_>>();
            fields.sort_by(|(a, _), (b, _)| a.cmp(b));
            for (name, field) in fields {
                object.insert(name.clone(), materialize_field(field));
            }
            Value::Object(Box::new(object))
        }
        FieldType::Enum(values) => values
            .first()
            .map(|value| json!(value))
            .unwrap_or_else(|| json!(null)),
        FieldType::OneOf(types) => types
            .first()
            .map(materialize_field_type)
            .unwrap_or_else(|| json!(null)),
        FieldType::Any => json!(null),
    }
}

/// Format a plugin's live state into a `PluginSchema`.
///
/// This is a *formatter*, not a schema authority — nothing here is indexed. The
/// plugin's live state (its `*State` struct) is the single source
/// of truth; field types are inferred from that state, so the schema can never
/// drift from what the plugin actually reports. To add a field, add it to the
/// plugin state — never hand-write a field definition.
pub(crate) fn schema_from_state(
    name: &str,
    category: &str,
    version: &str,
    description: &str,
    state: &Value,
) -> PluginSchema {
    use simd_json::prelude::*;

    let mut builder = PluginSchema::builder(name)
        .version(version)
        .category(category)
        .description(description);

    if let Some(obj) = state.as_object() {
        for (key, value) in obj.iter() {
            builder = builder.field(&key.to_string(), field_from_value(value));
        }
    }

    builder.example(state.clone()).build()
}

/// Infer a `FieldSchema` (type + example) from a live state value.
pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
    FieldSchema {
        field_type: infer_field_type(value),
        required: false,
        description: String::new(),
        default: None,
        example: Some(value.clone()),
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
pub(crate) fn infer_field_type(value: &Value) -> FieldType {
    use simd_json::prelude::*;

    if value.is_null() {
        FieldType::Any
    } else if value.as_bool().is_some() {
        FieldType::Boolean
    } else if value.as_i64().is_some() || value.as_u64().is_some() {
        FieldType::Integer
    } else if value.as_f64().is_some() {
        FieldType::Float
    } else if value.as_str().is_some() {
        FieldType::String
    } else if let Some(arr) = value.as_array() {
        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
        FieldType::Array(Box::new(inner))
    } else if let Some(obj) = value.as_object() {
        let fields = obj
            .iter()
            .map(|(k, v)| (k.to_string(), field_from_value(v)))
            .collect();
        FieldType::Object(fields)
    } else {
        FieldType::Any
    }
}

pub(crate) fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
    FieldSchema {
        field_type: FieldType::Any,
        required,
        description: description.to_string(),
        default,
        example: None,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

pub(crate) fn cap_method(
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    required_capability: &str,
    subid: &str,
) -> MethodDecl {
    MethodDecl {
        name: name.to_string(),
        args: json!({"type": "object", "additionalProperties": true}),
        returns: Some(json!({"type": "object", "additionalProperties": true})),
        side_effect,
        idempotent,
        required_capability: Some(required_capability.to_string()),
        subid: subid.to_string(),
    }
}

pub(crate) fn simple_schema(
    name: &str,
    description: &str,
    dependencies: &[&str],
    fields: Vec<(&str, FieldSchema)>,
) -> PluginSchema {
    let mut builder = PluginSchema::builder(name)
        .version("1.0.0")
        .description(description);
    for dep in dependencies {
        builder = builder.dependency(dep);
    }
    for (field_name, schema) in fields {
        builder = builder.field(field_name, schema);
    }
    builder.build()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn field(field_type: FieldType, default: Option<Value>, example: Option<Value>) -> FieldSchema {
        FieldSchema {
            field_type,
            required: false,
            description: String::new(),
            default,
            example,
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        }
    }

    #[test]
    fn materializes_seed_state_from_schema_defaults_examples_and_types() {
        let schema = PluginSchema::builder("example")
            .field(
                "enabled",
                field(FieldType::Boolean, Some(json!(true)), Some(json!(false))),
            )
            .field("label", field(FieldType::String, None, Some(json!("demo"))))
            .field(
                "mode",
                field(
                    FieldType::Enum(vec!["active".to_string(), "passive".to_string()]),
                    None,
                    None,
                ),
            )
            .field(
                "choice",
                field(
                    FieldType::OneOf(vec![FieldType::Integer, FieldType::String]),
                    None,
                    None,
                ),
            )
            .field(
                "nested",
                field(
                    FieldType::Object(HashMap::from([(
                        "count".to_string(),
                        field(FieldType::Integer, None, None),
                    )])),
                    None,
                    None,
                ),
            )
            .build();

        let state = materialize_state_from_schema(&schema);

        assert_eq!(state["enabled"], json!(true));
        assert_eq!(state["label"], json!("demo"));
        assert_eq!(state["mode"], json!("active"));
        assert_eq!(state["choice"], json!(0));
        assert_eq!(state["nested"]["count"], json!(0));
    }
}

//! OCI container plugin — schema-driven lifecycle for Docker/OCI containers
//! managed by incus that need host-side bootstrap (loopback, netns init).
//!
//! OCI containers in incus with no NIC device boot with lo DOWN, preventing
//! services from binding to 127.0.0.1. This plugin declares which containers
//! need loopback bring-up, and the op-openvswitch-daemon's BringUpLoopback
//! D-Bus method executes it.
//!
//! THE PLUGIN IS THE SCHEMA — if a container is declared here with
//! loopback_required=true, the daemon will bring up lo inside its netns.

use anyhow::Result;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema, ReadOnlyCondition};
use simd_json::json;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

// ── Schema definition — THE PLUGIN IS THE SCHEMA ─────────────────────────────

fn oci_container_fields() -> HashMap<String, FieldSchema> {
    let mut fields = HashMap::new();
    fields.insert(
        "name".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "Incus instance name (must match hostname inside container)".to_string(),
            default: None,
            example: Some(json!("netmaker")),
            constraints: Vec::new(),
            read_only: true,
            read_only_when: None,
        },
    );
    fields.insert(
        "image".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "OCI image reference (e.g. docker:gravitl/netmaker:v1.5.1)".to_string(),
            default: None,
            example: Some(json!("docker:gravitl/netmaker:v1.5.1")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "loopback_required".to_string(),
        FieldSchema {
            field_type: FieldType::Boolean,
            required: false,
            description: "Whether BringUpLoopback must run inside this container's netns before services start. Required for OCI containers with no NIC.".to_string(),
            default: Some(json!(false)),
            example: Some(json!(true)),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "entrypoint_override".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description: "Optional wrapper command prepended before the OCI entrypoint. Used for lo-up and other pre-service hooks.".to_string(),
            default: None,
            example: Some(json!("/usr/local/bin/lo-up-wrapper.sh")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "privileged".to_string(),
        FieldSchema {
            field_type: FieldType::Boolean,
            required: false,
            description: "Whether the container runs in privileged mode".to_string(),
            default: Some(json!(false)),
            example: Some(json!(true)),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "env".to_string(),
        FieldSchema {
            field_type: FieldType::Any,
            required: false,
            description: "Environment variables for the container".to_string(),
            default: Some(json!({})),
            example: Some(json!({"SERVER_HOST": "129.153.134.63", "API_PORT": "8081"})),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "sockets".to_string(),
        FieldSchema {
            field_type: FieldType::Any,
            required: false,
            description: "Proxy devices: unix socket listeners on host -> TCP inside container".to_string(),
            default: Some(json!([])),
            example: Some(json!([
                {"id": "api-sock", "listen": "unix:/run/netmaker/api.sock", "connect": "tcp:127.0.0.1:8081"}
            ])),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "volumes".to_string(),
        FieldSchema {
            field_type: FieldType::Any,
            required: false,
            description: "Disk device mounts (storage volumes)".to_string(),
            default: Some(json!([])),
            example: Some(json!([
                {"id": "nm-sqldata", "path": "/root/data", "source": "nm-sqldata"}
            ])),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields.insert(
        "port_attach".to_string(),
        FieldSchema {
            field_type: FieldType::Any,
            required: false,
            description: "OVS port attach config for this container (bridge, port_name, ip_addrs, gateway, routes). If present, ovs-attach calls AttachPort after BringUpLoopback.".to_string(),
            default: None,
            example: Some(json!({
                "bridge": "ovsbr0",
                "iface_name": "gbr_xray",
                "ip_addrs": ["10.200.0.1/30", "10.0.0.2/24"],
                "gateway": "10.200.0.2",
                "routes": ["10.0.0.1 via 10.200.0.2"]
            })),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    fields
}

pub(crate) fn oci_schema() -> PluginSchema {
    PluginSchema::builder("oci")
        .version("1.0.0")
        .category("container")
        .description("OCI container lifecycle — schema-driven loopback bring-up, netns init, and port attach for incus-managed Docker/OCI containers")
        .dependency("incus")
        .dependency("rovs_commands")
        .array_field(
            "containers",
            FieldType::Object(oci_container_fields()),
            true,
            "Declared OCI containers with lifecycle config",
        )
        .example(json!({
            "containers": [
                {
                    "name": "netmaker",
                    "image": "docker:gravitl/netmaker:v1.5.1",
                    "loopback_required": true,
                    "privileged": true,
                    "env": {
                        "SERVER_HOST": "129.153.134.63",
                        "API_PORT": "8081",
                        "DATABASE": "sqlite"
                    },
                    "sockets": [
                        {"id": "api-sock", "listen": "unix:/run/netmaker/api.sock", "connect": "tcp:127.0.0.1:8081"}
                    ],
                    "volumes": [
                        {"id": "nm-sqldata", "path": "/root/data", "source": "nm-sqldata"}
                    ]
                },
                {
                    "name": "netmaker-mq",
                    "image": "docker:eclipse-mosquitto:2.0.15-openssl",
                    "loopback_required": true,
                    "sockets": [
                        {"id": "mqtt-sock", "listen": "unix:/run/netmaker/mq.sock", "connect": "tcp:127.0.0.1:1883"},
                        {"id": "mqtts-sock", "listen": "unix:/run/netmaker/mqtts.sock", "connect": "tcp:127.0.0.1:8883"}
                    ]
                },
                {
                    "name": "netmaker-ui",
                    "image": "docker:gravitl/netmaker-ui:v1.5.1",
                    "loopback_required": true,
                    "sockets": [
                        {"id": "ui-sock", "listen": "unix:/run/netmaker/ui.sock", "connect": "tcp:127.0.0.1:80"}
                    ]
                }
            ]
        }))
        .build()
}

